package com.pvphud;

/** Immutable snapshot of the presentation settings for one HUD layout. */
class LayoutProfile
{
	final BuffStyle       buffStyle;
	final int             backgroundOpacity;
	final boolean         chatLocked;
	final BarDisplayStyle hpBarStyle;
	final BarDisplayStyle prayerBarStyle;
	final BarDisplayStyle runBarStyle;
	final BarDisplayStyle specBarStyle;

	LayoutProfile(BuffStyle buffStyle, int backgroundOpacity,
		boolean chatLocked,
		BarDisplayStyle hpBarStyle, BarDisplayStyle prayerBarStyle,
		BarDisplayStyle runBarStyle, BarDisplayStyle specBarStyle)
	{
		this.buffStyle         = buffStyle;
		this.backgroundOpacity = backgroundOpacity;
		this.chatLocked        = chatLocked;
		this.hpBarStyle        = hpBarStyle;
		this.prayerBarStyle    = prayerBarStyle;
		this.runBarStyle       = runBarStyle;
		this.specBarStyle      = specBarStyle;
	}

	/** Reads the profile for {@code layout} from the given config. */
	static LayoutProfile forLayout(HudLayout layout, PvpHudConfig config)
	{
		switch (layout)
		{
			case HORIZONTAL_FLOAT:
				return new LayoutProfile(
					config.hfBuffStyle(),
					config.hfBackgroundOpacity(),
					config.hfChatLocked(),
					config.hfHpBarStyle(),
					config.hfPrayerBarStyle(),
					config.hfRunBarStyle(),
					config.hfSpecBarStyle()
				);
			case VERTICAL_FLOAT:
				return new LayoutProfile(
					config.vfBuffStyle(),
					config.vfBackgroundOpacity(),
					false,
					config.vfHpBarStyle(),
					config.vfPrayerBarStyle(),
					config.vfRunBarStyle(),
					config.vfSpecBarStyle()
				);
			case INVENTORY_HUG:
			default:
				return new LayoutProfile(
					config.ihBuffStyle(),
					config.ihBackgroundOpacity(),
					false,
					config.ihHpBarStyle(),
					config.ihPrayerBarStyle(),
					config.ihRunBarStyle(),
					config.ihSpecBarStyle()
				);
		}
	}
}

package com.pvphud;

/**
 * Records the INTENT to consume an item (set on MenuOptionClicked).
 * Authoritative cooldowns are only applied once the inventory change confirms
 * that the item was actually consumed.
 *
 * Intents expire after MAX_AGE_TICKS to prevent stale matches against
 * unrelated later inventory updates.
 */
public final class PendingConsumable
{
	/** Maximum ticks before an unconfirmed intent is discarded. */
	static final int MAX_AGE_TICKS = 3;

	/** Item ID from the inventory slot at click time. */
	public final int itemId;

	/** Inventory slot index (0–27). */
	public final int slot;

	/** Client game tick when the menu option was clicked. */
	public final long intentTick;

	/** Derived classification (cached to avoid re-classifying on confirmation). */
	public final ConsumableType type;

	/** True once a confirming inventory change has been processed. */
	private boolean confirmed;

	PendingConsumable(int itemId, int slot, long intentTick, ConsumableType type)
	{
		this.itemId     = itemId;
		this.slot       = slot;
		this.intentTick = intentTick;
		this.type       = type;
	}

	boolean isConfirmed() { return confirmed; }

	void markConfirmed() { confirmed = true; }

	boolean isExpired(long currentTick)
	{
		return currentTick > intentTick + MAX_AGE_TICKS;
	}
}

