	// ── Config migration ──────────────────────────────────────────────────────

	/**
	 * One-shot config migration from the Plugin Hub v0 schema to v1.
	 * - Explicit CHAT_LOCKED layout is folded into HORIZONTAL_FLOAT with
	 *   hf_chatLocked=true.
	 * - Explicit HORIZONTAL_FLOAT users had no hf_chatLocked key before the
	 *   default flipped to true; we write "false" to preserve their intent
	 *   (unless the key is already set).
	 * - Users who kept the old CHAT_LOCKED default (no hudLayout key saved)
	 *   are covered by the hf_chatLocked=true default — this method does not
	 *   force the key for them.
	 * - Legacy top-level style keys (buffStyle, backgroundOpacity, hpBarStyle,
	 *   etc.) are copied into their hf_* equivalents when the hf_* key is not
	 *   already set. This is unconditional on hudLayout so that both explicit
	 *   CHAT_LOCKED users and legacy-default users get their customisations.
	 * The configVersion key is used as an idempotency guard.
	 */
	private void migrateOldConfig()
	{
		String versionStr = configManager.getConfiguration(CONFIG_GROUP, "configVersion");
		if ("1".equals(versionStr)) return;

		String layoutRaw = configManager.getConfiguration(CONFIG_GROUP, "hudLayout");
		if ("CHAT_LOCKED".equals(layoutRaw))
		{
			configManager.setConfiguration(CONFIG_GROUP, "hudLayout", "HORIZONTAL_FLOAT");
			configManager.setConfiguration(CONFIG_GROUP, "hf_chatLocked", "true");
		}
		else if ("HORIZONTAL_FLOAT".equals(layoutRaw))
		{
			// User explicitly chose free-floating. hfChatLocked now defaults
			// true, so write false here to preserve their intent — but only
			// when the key has not already been set.
			String existingPin = configManager.getConfiguration(CONFIG_GROUP, "hf_chatLocked");
			if (existingPin == null)
				configManager.setConfiguration(CONFIG_GROUP, "hf_chatLocked", "false");
		}
		// VERTICAL_FLOAT, INVENTORY_HUG: no hf_chatLocked action needed.
		// No hudLayout key (unsaved old default): hfChatLocked() default=true handles it.

		// Always copy old top-level style keys into hf_* equivalents when
		// present but the hf_* key is unset. Covers both explicit CHAT_LOCKED
		// users and users who kept the old default without saving the layout.
		copyIfAbsent("buffStyle",         "hf_buffStyle");
		copyIfAbsent("backgroundOpacity", "hf_backgroundOpacity");
		copyIfAbsent("hpBarStyle",        "hf_hpBarStyle");
		copyIfAbsent("prayerBarStyle",    "hf_prayerBarStyle");
		copyIfAbsent("runBarStyle",       "hf_runBarStyle");
		copyIfAbsent("specBarStyle",      "hf_specBarStyle");

		configManager.setConfiguration(CONFIG_GROUP, "configVersion", "1");
	}

	private void copyIfAbsent(String oldKey, String newKey)
	{
		String oldVal = configManager.getConfiguration(CONFIG_GROUP, oldKey);
		String newVal = configManager.getConfiguration(CONFIG_GROUP, newKey);
		if (oldVal != null && newVal == null)
			configManager.setConfiguration(CONFIG_GROUP, newKey, oldVal);
	}

	private void applyOverlayPosition()
	{
		// DYNAMIC overlays are excluded from RuneLite's Alt+drag overlay editor.
		// Float layouts need a non-DYNAMIC position so the user can drag them.
		switch (config.hudLayout())
		{
			case HORIZONTAL_FLOAT:
			case VERTICAL_FLOAT:
				overlay.setPosition(OverlayPosition.TOP_LEFT);
				break;
			default:
				overlay.setPosition(OverlayPosition.DYNAMIC);
				break;
		}
	}

	// ── Self state initialisation ─────────────────────────────────────────────

	private void initSelfState()
	{
		if (client.getGameState() != GameState.LOGGED_IN) return;

		hudState.getEffects().setSpecEnergy(
			client.getVarpValue(VarPlayer.SPECIAL_ATTACK_PERCENT) / 10);

		int poisonVal = client.getVarpValue(VarPlayer.POISON);
		SelfState   self  = hudState.getSelf();
		applyPoisonVarp(poisonVal);
		self.setCurrentHp(client.getBoostedSkillLevel(Skill.HITPOINTS));
		self.setMaxHp(client.getRealSkillLevel(Skill.HITPOINTS));
		self.setCurrentPrayer(client.getBoostedSkillLevel(Skill.PRAYER));
		self.setMaxPrayer(client.getRealSkillLevel(Skill.PRAYER));
		// client.getEnergy() returns 0-10000; divide by 100 for 0-100%
		self.setRunEnergy(client.getEnergy() / 100);
		int tbRaw = client.getVarbitValue(Varbits.TELEBLOCK);
		self.setTeleBlockTicksRemaining(decodeTeleblockTicks(tbRaw));
		self.setTbImmunityActive(tbRaw > 0 && tbRaw <= 100);

		EffectState fx   = hudState.getEffects();
		int         tick = client.getTickCount();
		fx.setDivineSupercombatTicks(client.getVarbitValue(Varbits.DIVINE_SUPER_COMBAT));
		fx.setDivineRangingTicks(client.getVarbitValue(Varbits.DIVINE_RANGING));
		fx.setDivineMagicTicks(client.getVarbitValue(Varbits.DIVINE_MAGIC));
		fx.setDivineBastionTicks(client.getVarbitValue(Varbits.DIVINE_BASTION));
		fx.setDivineBattlemageTicks(client.getVarbitValue(Varbits.DIVINE_BATTLEMAGE));
		fx.setDivineSuperAttackTicks(client.getVarbitValue(Varbits.DIVINE_SUPER_ATTACK));
		fx.setDivineSuperStrengthTicks(client.getVarbitValue(Varbits.DIVINE_SUPER_STRENGTH));
		fx.setDivineSuperDefenceTicks(client.getVarbitValue(Varbits.DIVINE_SUPER_DEFENCE));
		fx.setImbuedHeartCooldownTicks(client.getVarbitValue(Varbits.IMBUED_HEART_COOLDOWN));
		fx.updatePrayerRegen(client.getVarbitValue(Varbits.BUFF_PRAYER_REGENERATION));
		fx.updateSurgePotionFromVarbit(client.getVarbitValue(VarbitID.SURGE_POTION_TIMER), tick);
		fx.setBurnDamageTotal(client.getVarbitValue(VarbitID.PLAYER_OWN_BURN_DAMAGE_TOTAL));
		fx.setBurnDamageNextHit(client.getVarbitValue(VarbitID.PLAYER_OWN_BURN_DAMAGE_HITSPLAT_SIZE));
		fx.setCorruptionTargetIterations(client.getVarbitValue(VarbitID.CORRUPTION_TARGET_ITERATIONS));
		fx.setCorruptionCurrentIterations(client.getVarbitValue(VarbitID.CORRUPTION_CURRENT_ITERATIONS));
		fx.setCorruptionBaseDamage(client.getVarbitValue(VarbitID.CORRUPTION_BASE_DAMAGE));
		prevCorruptionIterations = client.getVarbitValue(VarbitID.CORRUPTION_CURRENT_ITERATIONS);
		if (client.getVarbitValue(Varbits.WARD_OF_ARCEUUS_COOLDOWN) > 0)
			fx.applyWardCooldown(tick);
		if (client.getVarbitValue(VarbitID.BUFF_MARK_OF_DARKNESS_DISABLED) > 0)
			fx.applyMarkCooldown(tick);
		int menVal = client.getVarbitValue(Varbits.MENAPHITE_REMEDY);
		fx.getMenaphite().setTotalTicksRemaining(menVal * 25);
		prevMenaphiteVarbit = menVal;
		// nextProcTicks stays 0 — we don't know where in the 25-tick cycle we joined.

		updateAmmo();

		// Antifire: if already active, assume the next boundary is one full interval away.
		// The varbit handler will correct the phase on the first observed decrement.
		int antifireVal = client.getVarbitValue(Varbits.ANTIFIRE);
		if (antifireVal > 0)
		{
			fx.setNextAntifireTick(tick + 30);
			fx.setAntifireVarbitValue(antifireVal);
		}
		int superAntifireVal = client.getVarbitValue(Varbits.SUPER_ANTIFIRE);
		if (superAntifireVal > 0)
		{
			fx.setNextSuperAntifireTick(tick + 20);
			fx.setSuperAntifireVarbitValue(superAntifireVal);
		}
		// Stamina effect is self-tracked (STAMINA_EFFECT is binary, not a countdown).
		// At startup we can't know remaining time, so we don't initialize the timer.
	}

	private void rehydrateFromClient()
	{
		if (client.getGameState() != GameState.LOGGED_IN) return;
		updateEnvironment();
		initSelfState();
		overlay.loadModIcons();
		hudState.getLayout().markDirty();
		overlay.invalidateInventoryHugAnchor();
	}

	// ── Config / game-state events ────────────────────────────────────────────

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals("pvp-hud")) return;
		if ("hudLayout".equals(event.getKey()))
		{
			applyOverlayPosition();
			overlay.invalidateInventoryHugAnchor();
		}
		hudState.getLayout().markDirty();
	}

	@Subscribe
	public void onCanvasSizeChanged(CanvasSizeChanged event)
	{
		overlay.onGameframeChanged();
	}

	@Subscribe
	public void onResizeableChanged(ResizeableChanged event)
	{
		overlay.onGameframeChanged();
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		// Invalidate when any top-level gameframe interface is (re)loaded.
		// Fixed viewport (548), resizable stretch (161), resizable pre-EOC (164).
		int g = event.getGroupId();
		if (g == InterfaceID.TOPLEVEL
			|| g == InterfaceID.TOPLEVEL_OSRS_STRETCH
			|| g == InterfaceID.TOPLEVEL_PRE_EOC)
		{
			overlay.onGameframeChanged();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGING_IN
			|| event.getGameState() == GameState.HOPPING)
		{
			lookedUp.clear();
			pendingConsumables.clear();
			pendingOpponentName      = null;
			pendingOpponentActor     = null;
			prevMenaphiteVarbit        = -1;
			prevCorruptionIterations   = -1;
			lastPlayerPos              = null;
			pendingHiscoreName         = null;
			hiscorePollStartTick       = -1;
			resetHiscoreResolution();
			opponentMissingTick        = -1;
			hudState.fullReset();
			overlay.invalidateInventoryHugAnchor();
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			rehydrateFromClient();
		}
	}

	// ── Stat changes ──────────────────────────────────────────────────────────

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		SelfState self = hudState.getSelf();
		switch (event.getSkill())
		{
			case HITPOINTS:
			{
				int prevHp = self.getCurrentHp();
				self.setCurrentHp(event.getBoostedLevel());
				self.setMaxHp(event.getLevel());
				if (event.getBoostedLevel() == 0 && prevHp > 0)
				{
					// Local player died — terminate the fight immediately.
					hudState.endSession();
					hudState.getOpponent().reset();
					pendingOpponentName  = null;
					pendingOpponentActor = null;
				}
				break;
			}
			case PRAYER:
				self.setCurrentPrayer(event.getBoostedLevel());
				self.setMaxPrayer(event.getLevel());
				break;
			default:
				break;
		}
	}

	/**
	 * Returns true when the cached tracked opponent is actively interacting with
	 * the local player (i.e., they are swinging at us this tick).
	 * Package-visible for unit testing.
	 */
	static boolean isTrackedOpponentTargetingUs(Object trackedInteracting, Object localPlayer)
	{
		return trackedInteracting != null && trackedInteracting == localPlayer;
	}

	// ── Varbit / VarPlayer changes ────────────────────────────────────────────

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varbitId = event.getVarbitId();
		int varpId   = event.getVarpId();
		int value    = event.getValue();

		if (varbitId == Varbits.TELEBLOCK)
		{
			hudState.getSelf().setTeleBlockTicksRemaining(decodeTeleblockTicks(value));
			hudState.getSelf().setTbImmunityActive(value > 0 && value <= 100);
		}
		else if (varbitId == Varbits.DIVINE_SUPER_COMBAT)
		{
			hudState.getEffects().setDivineSupercombatTicks(value);
		}
		else if (varbitId == Varbits.DIVINE_RANGING)
		{
			hudState.getEffects().setDivineRangingTicks(value);
		}
		else if (varbitId == Varbits.DIVINE_MAGIC)
		{
			hudState.getEffects().setDivineMagicTicks(value);
		}
		else if (varbitId == Varbits.DIVINE_BASTION)
		{
			hudState.getEffects().setDivineBastionTicks(value);
		}
		else if (varbitId == Varbits.DIVINE_BATTLEMAGE)
		{
			hudState.getEffects().setDivineBattlemageTicks(value);
		}
		else if (varbitId == Varbits.DIVINE_SUPER_ATTACK)
		{
			hudState.getEffects().setDivineSuperAttackTicks(value);
		}
		else if (varbitId == Varbits.DIVINE_SUPER_STRENGTH)
		{
			hudState.getEffects().setDivineSuperStrengthTicks(value);
		}
		else if (varbitId == Varbits.DIVINE_SUPER_DEFENCE)
		{
			hudState.getEffects().setDivineSuperDefenceTicks(value);
		}
		else if (varbitId == Varbits.IMBUED_HEART_COOLDOWN)
		{
			hudState.getEffects().setImbuedHeartCooldownTicks(value);
		}
		else if (varbitId == Varbits.BUFF_PRAYER_REGENERATION)
		{
			hudState.getEffects().updatePrayerRegen(value);
		}
		else if (varbitId == VarbitID.SURGE_POTION_TIMER)
		{
			hudState.getEffects().updateSurgePotionFromVarbit(value, client.getTickCount());
		}
		else if (varbitId == VarbitID.PLAYER_OWN_BURN_DAMAGE_TOTAL)
		{
			hudState.getEffects().setBurnDamageTotal(value);
		}
		else if (varbitId == VarbitID.PLAYER_OWN_BURN_DAMAGE_HITSPLAT_SIZE)
		{
			hudState.getEffects().setBurnDamageNextHit(value);
		}
		else if (varbitId == VarbitID.CORRUPTION_BASE_DAMAGE)
		{
			hudState.getEffects().setCorruptionBaseDamage(value);
		}
		else if (varbitId == VarbitID.CORRUPTION_TARGET_ITERATIONS)
		{
			hudState.getEffects().setCorruptionTargetIterations(value);
		}
		else if (varbitId == VarbitID.CORRUPTION_CURRENT_ITERATIONS)
		{
			int tick = client.getTickCount();
			if (prevCorruptionIterations >= 0 && value != prevCorruptionIterations)
				hudState.getEffects().onCorruptionIterationChanged(tick);
			hudState.getEffects().setCorruptionCurrentIterations(value);
			prevCorruptionIterations = value;
			if (value >= hudState.getEffects().getCorruptionTargetIterations()
				&& hudState.getEffects().getCorruptionTargetIterations() > 0)
			{
				hudState.getEffects().clearCorruption();
				prevCorruptionIterations = -1;
			}
		}
		else if (varbitId == Varbits.WARD_OF_ARCEUUS_COOLDOWN)
		{
			if (value > 0)
				hudState.getEffects().applyWardCooldown(client.getTickCount());
			else
				hudState.getEffects().clearWardCooldown();
		}
		else if (varbitId == VarbitID.BUFF_MARK_OF_DARKNESS_DISABLED)
		{
			if (value > 0)
				hudState.getEffects().applyMarkCooldown(client.getTickCount());
			else
				hudState.getEffects().clearMarkCooldown();
		}
		else if (varbitId == Varbits.MENAPHITE_REMEDY)
		{
			PeriodicEffect men = hudState.getEffects().getMenaphite();
			if (value == 0)
			{
				men.reset();
			}
			else
			{
				men.setTotalTicksRemaining(value * 25);
				if (prevMenaphiteVarbit > 0 && value < prevMenaphiteVarbit)
					men.setNextProcTicks(25); // proc just fired; next restore in 25 ticks
			}
			prevMenaphiteVarbit = value;
		}
		else if (varbitId == Varbits.ANTIFIRE)
		{
			int tick = client.getTickCount();
			EffectState efx = hudState.getEffects();
			if (value == 0)
			{
				efx.setNextAntifireTick(-1);
			}
			else if (efx.getNextAntifireTick() - tick <= 0)
			{
				// Phase unknown or expired — set the next boundary to one full interval away.
				efx.setNextAntifireTick(tick + 30);
			}
			efx.setAntifireVarbitValue(value);
		}
		else if (varbitId == Varbits.SUPER_ANTIFIRE)
		{
			int tick = client.getTickCount();
			EffectState efx = hudState.getEffects();
			if (value == 0)
			{
				efx.setNextSuperAntifireTick(-1);
			}
			else if (efx.getNextSuperAntifireTick() - tick <= 0)
			{
				efx.setNextSuperAntifireTick(tick + 20);
			}
			efx.setSuperAntifireVarbitValue(value);
		}
		else if (varbitId == Varbits.STAMINA_EFFECT)
		{
			// STAMINA_EFFECT is not a countdown varbit — it's a binary flag (1 = active, 0 = done).
			// We self-track the duration: 200 ticks (2 min) per dose, reset on each activation.
			if (value > 0)
				hudState.getEffects().setStaminaEffectTicks(200);
			else
				hudState.getEffects().setStaminaEffectTicks(0);
		}
		else if (varpId == VarPlayer.SPECIAL_ATTACK_PERCENT)
		{
			hudState.getEffects().setSpecEnergy(value / 10);
		}
		else if (varpId == VarPlayer.POISON)
		{
			applyPoisonVarp(value);
		}
	}

	// ── Self freeze detection ─────────────────────────────────────────────────

	@Subscribe
	public void onGraphicChanged(GraphicChanged event)
	{
		Actor actor = event.getActor();

		if (actor == client.getLocalPlayer())
		{
			int       tick = client.getTickCount();
			SelfState self = hudState.getSelf();
			for (ActorSpotAnim sa : actor.getSpotAnims())
			{
				int id = sa.getId();
				if (id == SpotanimID.BIND_IMPACT
					|| id == SpotanimID.SNARE_IMPACT
					|| id == SpotanimID.ENTANGLE_IMPACT)
				{
					// Standard binding spells: start timer directly from impact graphic,
					// matching RuneLite's TimersAndBuffsPlugin behaviour.
					self.applyFreeze(tick, freezeTicksForGraphic(id), freezeSpriteIdForGraphic(id));
					return;
				}
				if (freezeTicksForGraphic(id) > 0)
				{
					// Ice spells: cache for same-tick chat-message confirmation.
					lastFreezeGraphicId   = id;
					lastFreezeGraphicTick = tick;
					break;
				}
			}
		}
	}

	// ── Game tick ─────────────────────────────────────────────────────────────

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int tick = client.getTickCount();

		// Opponent missing grace period — end session if opponent remains despawned.
		if (opponentMissingTick >= 0)
		{
			boolean reappeared = false;
			List<Player> players = client.getPlayers();
			if (players != null)
			{
				OpponentState opp = hudState.getOpponent();
				for (Player p : players)
				{
					if (p != null && p.getName() != null
						&& p.getName().equalsIgnoreCase(opp.getName()))
					{
						reappeared = true;
						opp.setCachedActor(p);
						break;
					}
				}
			}
			if (reappeared)
			{
				opponentMissingTick = -1;
			}
			else if (tick - opponentMissingTick >= OPPONENT_GRACE_TICKS)
			{
				log.debug("Opponent missing for {} ticks — ending session", OPPONENT_GRACE_TICKS);
				hudState.endSession();
				hudState.getOpponent().reset();
				pendingOpponentName  = null;
				pendingOpponentActor = null;
				opponentMissingTick  = -1;
			}
		}

		// Poll the HiscoreManager cache for a pending opponent lookup.
		if (pendingHiscoreName != null)
		{
			if ((tick - hiscorePollStartTick) % HISCORE_RECHECK_TICKS == 0)
				checkHiscores();
		}

		SelfState self = hudState.getSelf();

		// Movement while frozen proves the freeze broke early.
		// Guard against the tick the freeze was applied (position may be stale).
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer != null)
		{
			WorldPoint pos = localPlayer.getWorldLocation();
			if (self.isFrozen(tick) && lastPlayerPos != null && !pos.equals(lastPlayerPos)
				&& tick != self.getFreezeStartTick())
				self.breakFreezeEarly();
			lastPlayerPos = pos;
		}

		// Natural freeze expiry: timer ran out — grants refreeze immunity.
		if (!self.isFrozen(tick) && self.getFreezeStartTick() >= 0)
			self.expireFreeze(tick);

		EffectState fxTick = hudState.getEffects();
		if (fxTick.getStaminaEffectTicks() > 0)
			fxTick.setStaminaEffectTicks(fxTick.getStaminaEffectTicks() - 1);
		fxTick.getMenaphite().tick();
		fxTick.getPrayerRegen().tick();
		hudState.getPoison().tick();

		// Action clock uses absolute tick deadlines — no decrement needed.
		// Expire any pending consumable intents that were never confirmed.
		pendingConsumables.removeIf(pc -> pc.isExpired(tick));

		// Run energy: polled each tick (no reliable varbit event fires for it)
		hudState.getSelf().setRunEnergy(client.getEnergy() / 100);

		// Expire stale fight session (no combat for ~30 s)
		PvpFightSession session = hudState.getCurrentSession();
		if (session != null && session.isStale(tick))
		{
			hudState.endSession();
			hudState.getOpponent().reset();
		}

		updateEnvironment();
		pollOpponentHealth();

		// Periodic mod-icon reload retry for ironman badge display.
		// Retries every 100 ticks when an opponent with non-NORMAL account type is tracked.
		if (--modIconRetryCountdown <= 0)
		{
			modIconRetryCountdown = 100;
			OpponentState opp2 = hudState.getOpponent();
			if (opp2.isTracked() && opp2.getStats().getAccountType() != OpponentStats.AccountType.NORMAL)
				clientThread.invoke(overlay::ensureModIconsLoaded);
		}
	}

	// ── Menu clicks ───────────────────────────────────────────────────────────

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = event.getMenuOption();
		switch (option)
		{
			case "Eat":
			case "Drink":
			{
				ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
				if (inv == null) break;
				int slot = event.getMenuEntry().getParam0();
				Item item = inv.getItem(slot);
				if (item == null) break;
				ConsumableType type = ConsumableType.classify(option, item.getId());
				if (type.isKnown())
				{
					long now = client.getTickCount();
					pendingConsumables.add(new PendingConsumable(item.getId(), slot, now, type));
				}
				break;
			}
			case "Attack":
			{
				// Confirm combat immediately on an explicit Attack click on a player,
				// but only when the attack is valid for the current zone/level range.
				Actor menuActor = event.getMenuEntry().getActor();
				if (menuActor instanceof Player)
				{
					Player p = (Player) menuActor;
					if (p.getName() != null && canAttackPlayer(p))
						confirmCombatCandidate(p.getName(), p);
				}
				break;
			}
		}
	}

	// ── Inventory change — consumable confirmation + SOTD unequip ──────────

	private void updateAmmo()
	{
		if (client.getGameState() != GameState.LOGGED_IN) return;
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		SelfState     self      = hudState.getSelf();
		if (equipment == null)
		{
			self.setAmmoItemId(-1);
			self.setAmmoQuantity(0);
			return;
		}
		Item ammo = equipment.getItem(EquipmentInventorySlot.AMMO.getSlotIdx());
		if (ammo == null)
		{
			self.setAmmoItemId(-1);
			self.setAmmoQuantity(0);
			return;
		}
		ItemStats         stats = itemManager.getItemStats(ammo.getId());
		ItemEquipmentStats eq   = stats != null ? stats.getEquipment() : null;
		if (!isSupportedAmmo(eq))
		{
			self.setAmmoItemId(-1);
			self.setAmmoQuantity(0);
			return;
		}
		self.setAmmoItemId(ammo.getId());
		self.setAmmoQuantity(ammo.getQuantity());
	}

	static boolean isSupportedAmmo(ItemEquipmentStats eq)
	{
		return eq != null && eq.getRstr() > 0;
	}

	private static boolean isSotdFamily(int itemId)
	{
		return itemId == ItemID.SOTD
			|| itemId == ItemID.TOXIC_SOTD
			|| itemId == ItemID.TOXIC_SOTD_CHARGED
			|| itemId == ItemID.BR_SOTD
			|| itemId == ItemID.STAFF_OF_LIGHT
			|| itemId == ItemID.STAFF_OF_BALANCE;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.EQUIPMENT.getId())
		{
			Item weapon = event.getItemContainer().getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
			if (weapon == null || !isSotdFamily(weapon.getId()))
				hudState.getEffects().clearStaffProt();
			updateAmmo();
		}
		if (event.getContainerId() != InventoryID.INVENTORY.getId()) return;
		if (pendingConsumables.isEmpty()) return;

		ItemContainer    inv         = event.getItemContainer();
		long             currentTick = client.getTickCount();
		ActionClockState clock       = hudState.getActionClock();

		Iterator<PendingConsumable> it = pendingConsumables.iterator();
		while (it.hasNext())
		{
			PendingConsumable pc = it.next();
			if (pc.isConfirmed() || pc.isExpired(currentTick))
			{
				it.remove();
				continue;
			}
			Item slotItem = inv.getItem(pc.slot);
			if (slotItem == null || slotItem.getId() != pc.itemId)
			{
				pc.markConfirmed();
				clock.applyConsumable(currentTick, pc.type);
				it.remove();
			}
		}
	}

	// ── Animation — attack delay ─────────────────────────────────────────────

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		Actor actor = event.getActor();
		if (actor == client.getLocalPlayer())
		{
			int   anim        = client.getLocalPlayer().getAnimation();
			Actor interacting = client.getLocalPlayer().getInteracting();
			// Positive attack confirmation: only known combat animations advance
			// the clock. Unknown animations are ignored — the "interacting with a
			// Player" guard provides a second check against stray allowlist IDs.
			if (AttackAnimations.isAttack(anim) && interacting instanceof Player)
			{
				int speed = getWeaponSpeed();
				if (speed > 0)
					hudState.getActionClock().setAttack(client.getTickCount(), speed);
			}
		}
	}

	// ── Interacting changed — combat candidate tracking ──────────────────────

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		Actor source = event.getSource();
		Actor target = event.getTarget();

		if (source == client.getLocalPlayer())
		{
			if (!(target instanceof Player))
			{
				// Targeting a non-player (NPC, nothing) — drop the pending candidate.
				// Do NOT clear the candidate on null target so the session survives brief
				// disengagement (e.g. movement flickers between attacks).
				if (target != null)
				{
					pendingOpponentName  = null;
					pendingOpponentActor = null;
				}
				return;
			}

			Player targetPlayer = (Player) target;
			String name = targetPlayer.getName();
			if (name == null) return;

			PvpFightSession session = hudState.getCurrentSession();

			// Re-targeting the current session opponent — keep session alive.
			if (session != null && name.equalsIgnoreCase(session.getOpponentName()))
			{
				hudState.getOpponent().setName(name);
				hudState.getOpponent().setCachedActor(targetPlayer);
				return;
			}

			// New target — record as candidate; wait for combat confirmation.
			pendingOpponentName  = name;
			pendingOpponentActor = targetPlayer;
		}
		else if (source instanceof Player && target == client.getLocalPlayer())
		{
			// Another player targeted us — record as candidate only if no session exists.
			// Combat is confirmed when a hitsplat from them lands on us.
			if (hudState.getCurrentSession() != null) return;
			Player sourcePlayer = (Player) source;
			String name = sourcePlayer.getName();
			if (name == null) return;
			pendingOpponentName  = name;
			pendingOpponentActor = sourcePlayer;
		}
	}

	// ── Opponent despawn — session lifecycle ─────────────────────────────────

	@Subscribe
	public void onPlayerDespawned(PlayerDespawned event)
	{
		Player player = event.getPlayer();
		if (player == null || player.getName() == null) return;
		OpponentState opp = hudState.getOpponent();
		if (!opp.isTracked()) return;
		if (player.getName().equalsIgnoreCase(opp.getName()))
			opponentMissingTick = client.getTickCount();
	}

	/**
	 * Starts (or refreshes) a fight session for the given player.
	 * Safe to call multiple times for the same opponent.
	 */
	private void confirmCombatCandidate(String name, Player actor)
	{
		PvpFightSession session = hudState.getCurrentSession();
		if (session != null && name.equalsIgnoreCase(session.getOpponentName()))
		{
			hudState.getOpponent().setName(name);
			hudState.getOpponent().setCachedActor(actor);
			opponentMissingTick = -1;
			return;
		}
		// New opponent — start fresh.
		hudState.getOpponent().reset();
		hudState.getOpponent().setName(name);
		hudState.getOpponent().setCachedActor(actor);
		hudState.beginSession(name, client.getTickCount());
		enqueueHiscoresLookup(name);
		pendingOpponentName  = null;
		pendingOpponentActor = null;
		opponentMissingTick  = -1;
	}

	/** True if the target player can be attacked in the current zone and at the current combat level. */
	private boolean canAttackPlayer(Player target)
	{
		if (!hudState.getContext().isInPvpZone()) return false;
		int wildLevel = hudState.getContext().getWildernessLevel();
		if (wildLevel == 0) return true; // PvP world — no level-range restriction
		int myLevel    = client.getLocalPlayer().getCombatLevel();
		int theirLevel = target.getCombatLevel();
		return Math.abs(myLevel - theirLevel) <= wildLevel;
	}

	// ── Hitsplat events — combat log and HP estimation ────────────────────────

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Actor actor = event.getActor();

		if (actor == client.getLocalPlayer())
		{
			int dmg = event.getHitsplat().getAmount();

			// Incoming hitsplat confirms the pending candidate if they are currently
			// interacting with the local player (i.e., they are the attacker).
			if (pendingOpponentName != null && hudState.getCurrentSession() == null
				&& pendingOpponentActor != null
				&& pendingOpponentActor.getInteracting() == client.getLocalPlayer())
			{
				confirmCombatCandidate(pendingOpponentName, pendingOpponentActor);
			}

			int tick = client.getTickCount();
			PvpFightSession session = hudState.getCurrentSession();
			if (dmg <= 0)
			{
				// 0-splat keeps the session alive only when the tracked opponent
				// is actively targeting us (guards against NPC splashes and
				// multi-combat 3rd-party 0-hits).
				if (session != null)
				{
					Player tracked = hudState.getOpponent().getCachedActor();
					Object interacting = tracked != null ? tracked.getInteracting() : null;
					if (isTrackedOpponentTargetingUs(interacting, client.getLocalPlayer()))
						session.touchCombat(tick);
				}
				return;
			}

			// Only shake on actual damage — 0-splat must not trigger the animation.
			recordIncomingDamage(hudState.getSelf(), dmg, System.currentTimeMillis());

			if (session == null) return;
			session.onIncomingHit(dmg, tick);
		}
		else if (actor instanceof Player)
		{
			String actorName = actor.getName();
			if (actorName == null) return;

			// Only process hitsplats that we dealt — filters multi-combat hits
			// from other players landing on the same opponent.
			if (!event.getHitsplat().isMine()) return;

			// Outgoing hitsplat on the pending candidate confirms the session.
			if (pendingOpponentName != null && actorName.equalsIgnoreCase(pendingOpponentName))
			{
				Player pending = pendingOpponentActor != null ? pendingOpponentActor : (Player) actor;
				confirmCombatCandidate(pendingOpponentName, pending);
			}

			// Outgoing hit: hitsplat on the tracked opponent
			OpponentState opp = hudState.getOpponent();
			if (!opp.isTracked() || !actorName.equalsIgnoreCase(opp.getName()))
			{
				return;
			}

			int tick = client.getTickCount();
			int dmg  = event.getHitsplat().getAmount();
			if (dmg <= 0)
			{
				PvpFightSession session = hudState.getCurrentSession();
				if (session != null) session.touchCombat(tick);
				return;
			}

			handleOutgoingHit(opp, dmg, tick);
		}
	}

	/**
	 * Records a positive incoming damage event into {@link SelfState} for the
	 * HP-bar shake animation. No-op for zero or negative damage — 0-splashes
	 * must not trigger the shake.
	 *
	 * Package-visible so unit tests can exercise the exact production path.
	 */
	static void recordIncomingDamage(SelfState self, int damage, long nowMs)
	{
		if (damage <= 0) return;
		self.setLastIncomingDamageMs(nowMs);
		self.setLastIncomingDamage(damage);
	}

	private void handleOutgoingHit(OpponentState opp, int damage, int tick)
	{
		opp.setLastOutgoingHitMs(System.currentTimeMillis());

		if (opp.getEstimatedHp() > 0)
			opp.setEstimatedHp(Math.max(0, opp.getEstimatedHp() - damage));

		PvpFightSession session = hudState.getCurrentSession();
		if (session == null) return;

		// Outgoing Smite: local player's overhead icon determines drain amount
		int prayerDrain = 0;
		Player local = client.getLocalPlayer();
		if (local != null && local.getOverheadIcon() == HeadIcon.SMITE)
			prayerDrain = damage / 4;

		session.onOutgoingHit(damage, prayerDrain, tick);

		// Confirmed visual uses the same-tick exchange total so multi-hit attacks
		// (e.g. 22 + 16 on the same tick) show the authoritative total (38), not
		// whichever individual hitsplat arrived last.
		com.pvphud.state.DamageExchange exchange = session.getExchangeForTick(tick);
		opp.setLastOutgoingHit(exchange != null ? exchange.getOutgoingTotal() : damage);
	}

	// ── HUD visibility predicate ─────────────────────────────────────────────

	/**
	 * Single source of truth for whether the HUD should render.
	 * Extracted as a static method so it is unit-testable without a live Client.
	 */
	static boolean computeShouldShow(boolean enabled, HudMode mode, boolean inPvpZone, boolean hasSession)
	{
		if (!enabled) return false;
		switch (mode)
		{
			case MANUAL:   return true;
			case PVP_AREA: return inPvpZone;
			case AUTO:     return hasSession;
			default:       return false;
		}
	}

	boolean shouldShowHud()
	{
		return computeShouldShow(
			config.hudVisible(),
			config.hudMode(),
			hudState.getContext().isInPvpZone(),
			hudState.getCurrentSession() != null);
	}

	// ── Environment polling ───────────────────────────────────────────────────

	private void updateEnvironment()
	{
		boolean inWilderness = client.getVarbitValue(Varbits.IN_WILDERNESS) == 1;
		java.util.Set<WorldType> worldTypes = client.getWorldType();
		boolean onPvpWorld   = worldTypes != null && worldTypes.contains(WorldType.PVP);
		hudState.getContext().setInPvpZone(inWilderness || onPvpWorld);
		int wildLevel = 0;
		if (inWilderness)
		{
			Player local = client.getLocalPlayer();
			if (local != null)
			{
				WorldPoint loc = local.getWorldLocation();
				if (loc.getPlane() == 0)
				{
					wildLevel = (loc.getY() - 3520) / 8 + 1;
					wildLevel = Math.max(1, Math.min(56, wildLevel));
				}
			}
		}
		hudState.getContext().setWildernessLevel(wildLevel);
		hudState.getContext().setMultiCombat(client.getVarbitValue(Varbits.MULTICOMBAT_AREA) == 1);
	}

	private void pollOpponentHealth()
	{
		OpponentState opp = hudState.getOpponent();
		if (!opp.isTracked()) return;

		// Use cached Player reference; fall back to a full scan if it is stale
		Player p = opp.getCachedActor();
		if (p == null || p.getName() == null || !p.getName().equalsIgnoreCase(opp.getName()))
		{
			p = null;
			List<Player> players = client.getPlayers();
			if (players != null)
			{
				for (Player candidate : players)
				{
					if (candidate != null && candidate.getName() != null
						&& candidate.getName().equalsIgnoreCase(opp.getName()))
					{
						p = candidate;
						opp.setCachedActor(p);
						break;
					}
				}
			}
			if (p == null) return;
		}

		opp.setOverheadPrayer(p.getOverheadIcon());

		int ratio = p.getHealthRatio();
		int scale = p.getHealthScale();
		if (ratio < 0 || scale <= 0) return;

		// Terminate fight session when opponent HP reaches 0
		if (ratio == 0)
		{
			// In single-combat, opponent death ends the freeze on us (they can't re-freeze).
			if (!hudState.getContext().isMultiCombat())
				hudState.getSelf().breakFreezeEarly();
			hudState.endSession();
			hudState.getOpponent().reset();
			return;
		}

		// Hiscores HP is authoritative when available.
		int hiscoresHp = opp.getStats().getHitpoints();
		if (hiscoresHp > 0)
		{
			opp.setMaxHp(hiscoresHp);
			opp.setEstimatedHp((int) Math.round(hiscoresHp * (double) ratio / scale));
			return;
		}

		// Fall back to back-calculation from damage dealt until hiscores load.
		PvpFightSession session   = hudState.getCurrentSession();
		int             totalDealt = session != null ? session.getTotalOutgoing() : 0;

		if (opp.getMaxHp() <= 0)
		{
			if (ratio < scale && totalDealt > 0)
			{
				double missingFraction = 1.0 - (double) ratio / scale;
				if (missingFraction > 0.01)
				{
					int estimated = (int) Math.round(totalDealt / missingFraction);
					if (estimated >= 60 && estimated <= 200)
					{
						opp.setMaxHp(estimated);
						opp.setEstimatedHp((int) Math.round(estimated * (double) ratio / scale));
					}
				}
			}
		}
		else
		{
			opp.setEstimatedHp((int) Math.round(opp.getMaxHp() * (double) ratio / scale));
		}
	}

	// ── Weapon / freeze helpers ───────────────────────────────────────────────

	private int getWeaponSpeed()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null) return 0;
		Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon == null) return 0;
		ItemStats stats = itemManager.getItemStats(weapon.getId());
		if (stats == null) return 0;
		ItemEquipmentStats eq = stats.getEquipment();
		if (eq == null) return 0;
		int speed = eq.getAspeed();
		return speed > 0 ? speed : 0;
	}

	/**
	 * Decode raw {@code Varbits.TELEBLOCK} value to active TB ticks remaining.
	 * Raw 0      = not active, no immunity.
	 * Raw 1..100 = post-TB reapplication immunity only (TB itself has expired).
	 * Raw 101+   = TB active; remaining = raw - 100.
	 * Mirrors RuneLite TimersAndBuffsPlugin: {@code event.getValue() - 100}.
	 */
	static int decodeTeleblockTicks(int raw)
	{
		return Math.max(0, raw - 100);
	}

	static int freezeTicksForGraphic(int graphicId)
	{
		switch (graphicId)
		{
			case GraphicID.ICE_RUSH:           return 8;
			case GraphicID.ICE_BURST:          return 16;
			case GraphicID.ICE_BLITZ:          return 24;
			case GraphicID.ICE_BARRAGE:        return 32;
			case SpotanimID.BIND_IMPACT:       return 8;
			case SpotanimID.SNARE_IMPACT:      return 16;
			case SpotanimID.ENTANGLE_IMPACT:   return 24;
			default:                           return 0;
		}
	}

	static int freezeSpriteIdForGraphic(int graphicId)
	{
		switch (graphicId)
		{
			case GraphicID.ICE_RUSH:           return SpriteID.SPELL_ICE_RUSH;
			case GraphicID.ICE_BURST:          return SpriteID.SPELL_ICE_BURST;
			case GraphicID.ICE_BLITZ:          return SpriteID.SPELL_ICE_BLITZ;
			case GraphicID.ICE_BARRAGE:        return SpriteID.SPELL_ICE_BARRAGE;
			case SpotanimID.BIND_IMPACT:       return SpriteID.SPELL_BIND;
			case SpotanimID.SNARE_IMPACT:      return SpriteID.SPELL_SNARE;
			case SpotanimID.ENTANGLE_IMPACT:   return SpriteID.SPELL_ENTANGLE;
			default:                           return SpriteID.SPELL_ICE_BARRAGE;
		}
	}

	// ── Freeze detection — chat message is the authoritative trigger ──────────────

	/**
	 * "You have been frozen!" is a SPAM-type game message that fires exactly once
	 * when a freeze successfully applies. Using it (rather than the graphic) as the
	 * trigger ensures repeated ice hits while already frozen do not extend the timer.
	 *
	 * The same-tick graphic (captured in onGraphicChanged or read from live spot
	 * anims) is used only to identify which spell was cast so the correct base
	 * duration can be selected — it does not drive the freeze by itself.
	 */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (type != ChatMessageType.SPAM && type != ChatMessageType.GAMEMESSAGE) return;

		String      msg  = Text.removeTags(event.getMessage());
		int         tick = client.getTickCount();
		SelfState   self = hudState.getSelf();
		EffectState fx   = hudState.getEffects();

		if (type == ChatMessageType.GAMEMESSAGE)
		{
			if (msg.contains(SOTD_SPEC_ON_MSG))
				fx.applyStaffProt(tick);
			else if (msg.contains(SOTD_SPEC_OFF_MSG))
				fx.clearStaffProt();
			else if (msg.endsWith(WARD_ON_MSG))
			{
				fx.applyWardOfArceuus(tick, client.getRealSkillLevel(Skill.MAGIC));
				fx.applyWardCooldown(tick);
			}
			else if (msg.endsWith(MARK_ON_MSG))
			{
				fx.applyMarkOfDarkness(tick, client.getRealSkillLevel(Skill.MAGIC));
				fx.applyMarkCooldown(tick);
			}
			return;
		}

		// ChatMessageType.SPAM below:
		if (msg.contains("protection prayers have been disabled"))
		{
			self.applyPrayerLock(tick);
			return;
		}

		if (!msg.equals("You have been frozen!") && !msg.equals("You are frozen.")) return;

		// Try live spot anims first (most reliable when graphic fires before message)
		int graphicId = -1;
		Player local = client.getLocalPlayer();
		if (local != null)
		{
			for (ActorSpotAnim sa : local.getSpotAnims())
			{
				if (freezeTicksForGraphic(sa.getId()) > 0)
				{
					graphicId = sa.getId();
					break;
				}
			}
		}
		// Fall back to the cached graphic if it landed on the same tick
		if (graphicId < 0 && lastFreezeGraphicTick == tick)
		{
			graphicId = lastFreezeGraphicId;
		}

		// Ancient sceptre extends ice-spell freeze durations, but we cannot reliably
		// determine whether the attacker held one — we only see the incoming freeze,
		// not the opponent's equipment. Base duration is used unconditionally.
		int duration = graphicId >= 0 ? freezeTicksForGraphic(graphicId) : 32;
		int spriteId = graphicId >= 0 ? freezeSpriteIdForGraphic(graphicId) : SpriteID.SPELL_ICE_BARRAGE;

		self.applyFreeze(tick, duration, spriteId);
	}

	// ── Poison / venom / immunity ─────────────────────────────────────────────────

	/**
	 * Applies the POISON VarPlayer value to PoisonState.
	 * Positive = poisoned/venomed; negative = immunity.
	 * Values strictly below VENOM_VALUE_CUTOFF (-38) are anti-venom;
	 * values from -38 to -1 inclusive are anti-poison.
	 *
	 * nextPoisonTick synchronisation mirrors RuneLite's TimersAndBuffsPlugin:
	 * cleared on value 0, otherwise only reset when the existing tick has expired.
	 */
	private void applyPoisonVarp(int value)
	{
		PoisonState ps  = hudState.getPoison();
		int         now = client.getTickCount();
		ps.setVenomed(value >= 1_000_000);
		ps.setPoisoned(value > 0 && value < 1_000_000);
		if (value < PoisonState.VENOM_VALUE_CUTOFF)
		{
			ps.setAntiVenomActive(true);
			ps.setAntiPoisonActive(false);
			ps.setPoisonVarpValue(value);
			if (ps.getNextPoisonTick() - now <= 0)
				ps.setNextPoisonTick(now + PoisonState.POISON_TICK_LENGTH);
		}
		else if (value < 0)
		{
			ps.setAntiPoisonActive(true);
			ps.setAntiVenomActive(false);
			ps.setPoisonVarpValue(value);
			if (ps.getNextPoisonTick() - now <= 0)
				ps.setNextPoisonTick(now + PoisonState.POISON_TICK_LENGTH);
		}
		else
		{
			ps.setAntiVenomActive(false);
			ps.setAntiPoisonActive(false);
			ps.setPoisonVarpValue(0);
			ps.setNextPoisonTick(-1);
		}
	}

	// ── Hiscores lookup ───────────────────────────────────────────────────────────

	private void enqueueHiscoresLookup(String playerName)
	{
		String key = playerName.toLowerCase();
		if (!lookedUp.add(key)) return;
		log.debug("PvP HUD hiscores lookup queued: {}", playerName);
		pendingHiscoreName   = playerName;
		hiscorePollStartTick = client.getTickCount();
		resetHiscoreResolution();
		checkHiscores();
	}

	/** Clears per-lookup resolution state so a new lookup starts from scratch. */
	private void resetHiscoreResolution()
	{
		hiscoreBestAccountType = OpponentStats.AccountType.NORMAL;
	}

	/**
	 * Polls the HiscoreManager cache for the pending opponent. Called from onGameTick
	 * every HISCORE_RECHECK_TICKS until a verdict is reached or the timeout expires.
	 * HiscoreManager.lookupAsync returns cached data immediately or null; the first call
	 * also triggers a background refresh.
	 *
	 * <p>Semantics: {@code lookupAsync} returns null both for "still loading" and
	 * "player not on this endpoint", so there is no reliable "resolved negative"
	 * signal. Each poll checks every endpoint, upgrades
	 * {@link #hiscoreBestAccountType} to the highest-precedence positive hit
	 * observed, and commits at the deadline. A HC-positive observation
	 * terminates the loop immediately because nothing outranks HC.
	 */
	private void checkHiscores()
	{
		if (pendingHiscoreName == null) return;
		String name = pendingHiscoreName;

		OpponentState opp = hudState.getOpponent();
		if (!opp.isTracked() || !name.equalsIgnoreCase(opp.getName()))
		{
			pendingHiscoreName = null;
			resetHiscoreResolution();
			return;
		}

		boolean normalDone = opp.getStats().getHitpoints() > 0;

		if (!normalDone)
		{
			HiscoreResult r = hiscoreManager.lookupAsync(name, HiscoreEndpoint.NORMAL);
			if (r != null)
			{
				applyHiscoresResult(name, r);
				normalDone = opp.getStats().getHitpoints() > 0;
			}
		}

		// HC takes immediate precedence — nothing outranks it, so a positive HC
		// observation lets us finish without waiting for the deadline.
		HiscoreResult hc = hiscoreManager.lookupAsync(name, HiscoreEndpoint.HARDCORE_IRONMAN);
		if (hc != null && skillLevel(hc, HiscoreSkill.HITPOINTS) > 0)
		{
			hiscoreBestAccountType = HiscoreAccountResolver.best(
				hiscoreBestAccountType, OpponentStats.AccountType.HARDCORE_IRONMAN);
			applyAccountType(name, hiscoreBestAccountType);
			pendingHiscoreName = null;
			resetHiscoreResolution();
			return;
		}

		// UIM / IM: record positive hits but keep polling until the deadline —
		// a HC lookup may still resolve on a later tick.
		HiscoreResult uim = hiscoreManager.lookupAsync(name, HiscoreEndpoint.ULTIMATE_IRONMAN);
		if (uim != null && skillLevel(uim, HiscoreSkill.HITPOINTS) > 0)
		{
			hiscoreBestAccountType = HiscoreAccountResolver.best(
				hiscoreBestAccountType, OpponentStats.AccountType.ULTIMATE_IRONMAN);
		}

		HiscoreResult im = hiscoreManager.lookupAsync(name, HiscoreEndpoint.IRONMAN);
		if (im != null && skillLevel(im, HiscoreSkill.HITPOINTS) > 0)
		{
			hiscoreBestAccountType = HiscoreAccountResolver.best(
				hiscoreBestAccountType, OpponentStats.AccountType.IRONMAN);
		}

		// Deadline — commit the best observed verdict (if any).
		if ((client.getTickCount() - hiscorePollStartTick) >= HISCORE_TIMEOUT_TICKS)
		{
			log.debug("PvP HUD hiscores deadline for {} — best={}", name, hiscoreBestAccountType);
			if (hiscoreBestAccountType != OpponentStats.AccountType.NORMAL)
			{
				applyAccountType(name, hiscoreBestAccountType);
			}
			pendingHiscoreName = null;
			resetHiscoreResolution();
		}
	}

	private void applyAccountType(String playerName, OpponentStats.AccountType type)
	{
		OpponentState opp = hudState.getOpponent();
		if (!opp.isTracked() || !playerName.equalsIgnoreCase(opp.getName())) return;
		if (type.ordinal() > opp.getStats().getAccountType().ordinal())
		{
			opp.getStats().setAccountType(type);
			log.debug("AccountType set for {}: {}", playerName, type);
			overlay.ensureModIconsLoaded();
			overlay.logBadgeCacheState(playerName, type);
		}
	}

	private void applyHiscoresResult(String playerName, HiscoreResult result)
	{
		int attack    = skillLevel(result, HiscoreSkill.ATTACK);
		int defence   = skillLevel(result, HiscoreSkill.DEFENCE);
		int strength  = skillLevel(result, HiscoreSkill.STRENGTH);
		int hitpoints = skillLevel(result, HiscoreSkill.HITPOINTS);
		int ranged    = skillLevel(result, HiscoreSkill.RANGED);
		int magic     = skillLevel(result, HiscoreSkill.MAGIC);

		OpponentState opp = hudState.getOpponent();
		if (!opp.isTracked() || !playerName.equalsIgnoreCase(opp.getName())) return;
		opp.getStats().setAttack(attack);
		opp.getStats().setDefence(defence);
		opp.getStats().setStrength(strength);
		opp.getStats().setHitpoints(hitpoints);
		opp.getStats().setRanged(ranged);
		opp.getStats().setMagic(magic);
		if (hitpoints > 0) opp.setMaxHp(hitpoints);
	}

	private static int skillLevel(HiscoreResult result, HiscoreSkill skill)
	{
		net.runelite.client.hiscore.Skill s = result.getSkill(skill);
		return s != null && s.getLevel() > 0 ? s.getLevel() : -1;
	}

	@Provides
	PvpHudConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PvpHudConfig.class);
	}
}

package com.pvphud;

import com.pvphud.state.ActionClockState;
import com.pvphud.state.EffectState;
import com.pvphud.state.HudLayoutState;
import com.pvphud.state.ManualTimerState;
import com.pvphud.state.OpponentState;
import com.pvphud.state.PoisonState;
import com.pvphud.state.PvpContextState;
import com.pvphud.state.PvpFightSession;
import com.pvphud.state.SelfState;
import lombok.Getter;

/**
 * Root state container for the PvP HUD.
 *
 * The overlay reads from this object; event handlers in the plugin update it.
 * All sub-states are pre-allocated at startup so combat initiation is cheap.
 *
 * Fight-specific data (event log, totals) live in the nullable currentSession.
 * A session is confirmed by an Attack menu click or a confirmed PvP hitsplat.
 * It ends on opponent death, local death, inactivity timeout, opponent despawn
 * past the grace window, logout/world hop, or plugin shutdown.
 */
@Getter
public class PvpHudState
{
	private final PvpContextState  context     = new PvpContextState();
	private final OpponentState    opponent    = new OpponentState();
	private final SelfState        self        = new SelfState();
	private final ActionClockState actionClock = new ActionClockState();
	private final EffectState      effects     = new EffectState();
	private final PoisonState      poison      = new PoisonState();
	private final ManualTimerState timer1      = new ManualTimerState();
	private final ManualTimerState timer2      = new ManualTimerState();
	private final HudLayoutState   layout      = new HudLayoutState();

	/** Active fight session; null between fights. */
	private PvpFightSession currentSession;

	/** Wall-clock ms when the last session ended; -1 = no session has ended yet. */
	@Getter private long sessionEndedMs = -1;

	/** Totals from the most recently ended session (for post-fight display). */
	@Getter private int lastTotalOutgoing;
	@Getter private int lastTotalIncoming;

	/** Start a new fight session. Any previous session is discarded. */
	public void beginSession(String opponentName, int tick)
	{
		currentSession = new PvpFightSession(opponentName, tick);
	}

	/** Terminate the active session (fight ended). Null-safe. */
	public void endSession()
	{
		if (currentSession != null)
		{
			lastTotalOutgoing = currentSession.getTotalOutgoing();
			lastTotalIncoming = currentSession.getTotalIncoming();
			currentSession.terminate();
			currentSession = null;
			sessionEndedMs = System.currentTimeMillis();
		}
	}

	/** Full reset on logout, world-hop, or plugin shutdown. */
	public void fullReset()
	{
		context.reset();
		opponent.reset();
		self.reset();
		actionClock.reset();
		effects.reset();
		poison.reset();
		layout.reset();
		endSession();
		sessionEndedMs = -1;
		lastTotalOutgoing = 0;
		lastTotalIncoming = 0;
	}
}

package com.pvphud;

/**
 * Four-tier priority for HUD status slots.
 * Render order: CRITICAL → TACTICAL → SUSTAIN → READINESS.
 * Overflow policy: CRITICAL is never displaced; lower tiers drop first.
 */
public enum StatusPriority
{
	/** Hard restrictions that immediately cap what the player can do: freeze, teleblock, prayer lock, corruption. */
	CRITICAL,

	/** Active threats and time-limited tactical buffs: poison/venom, burn, SOTD, ward, mark. */
	TACTICAL,

	/** Ongoing sustain and protection effects: anti-venom/poison, divines, menaphite, prayer regen, stamina, antifire. */
	SUSTAIN,

	/** Passive cooldowns with no urgency: imbued heart cooldown, surge potion. */
	READINESS
}

package com.pvphud;

import com.pvphud.state.EffectState;
import com.pvphud.state.PoisonState;
import com.pvphud.state.SelfState;
import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.SpriteID;

/**
 * Projects PvP state into an ordered list of {@link StatusSlot}s for HUD rendering.
 *
 * <p>Lifecycle slots: Freeze↔Refreeze Immunity, TB↔TB Immunity, Ward↔Ward CD,
 * Mark↔Mark CD each occupy a single logical slot — only one state is ever visible.
 *
 * <p>Compound statuses: Corruption, Burn, Prayer Regen, and Menaphite each emit
 * a primary slot followed by an {@code isSecondary=true} sub-entry for the next
 * proc/drain/hit countdown. Secondary entries are hidden in ICON_TRAY and 2-col.
 *
 * <p>Icons are not resolved here; callers use the {@code slotId} field to look
 * up icons in {@link PvpHudOverlay#getIconFor}.
 */
public final class StatusProjector
{
	// ── Colour palette ────────────────────────────────────────────────────────
	static final Color LIGHT_BLUE  = new Color(100, 185, 255);
	static final Color ORANGE      = new Color(255, 145,   0);
	static final Color RED         = new Color(220,  60,  60);
	static final Color TOXIC_GREEN = new Color(110, 230,  60);
	static final Color YELLOW      = new Color(255, 203,   5);
	static final Color GREEN       = new Color( 10, 210,  80);

	private StatusProjector() {}

	/**
	 * Builds the semantic slot list for one HUD frame.
	 *
	 * @param config   presentation config; may be {@code null} when {@code showAll=true}
	 * @param showAll  true to bypass config visibility guards, primarily for tests
	 */
	public static List<StatusSlot> project(
		SelfState self, EffectState fx, PoisonState poison,
		int tick, PvpHudConfig config, boolean showAll)
	{
		List<StatusSlot> out = new ArrayList<>(24);
		Color freezeHighlight = (config != null) ? config.barrageHighlightColor() : null;
		Color tbHighlight     = (config != null) ? config.tbHighlightColor()      : null;

		// ── CRITICAL ──────────────────────────────────────────────────────────
		// Freeze ↔ Refreeze Immunity: exactly one can show at a time
		int freeze = self.getFreezeTicksRemaining(tick);
		if (freeze > 0 && (showAll || config.showFreezeTimer()))
		{
			String t = formatFreezeRemaining(freeze);
			out.add(new StatusSlot(freezeSlotId(self.getFreezeSpriteId()),
				StatusPriority.CRITICAL, t, "ICE " + t, LIGHT_BLUE, freezeHighlight, false));
		}
		else
		{
			int refreezeImm = self.getRefreezeImmunityTicks(tick);
			if (refreezeImm > 0 && (showAll || config.showFreezeTimer()))
			{
				String t = refreezeImm + "t";
				out.add(new StatusSlot("freeze_imm", StatusPriority.CRITICAL, t, "REFRZ " + t,
					LIGHT_BLUE, false));
			}
		}

		// Teleblock ↔ TB Immunity: exactly one can show at a time
		int tb = self.getTeleBlockTicksRemaining();
		if (tb > 0)
		{
			String t = ticksToMSS(tb);
			out.add(new StatusSlot("tb", StatusPriority.CRITICAL, t, "TB " + t,
				ORANGE, tbHighlight, false));
		}
		else if (self.isTbImmunityActive())
		{
			out.add(new StatusSlot("tb_imm", StatusPriority.CRITICAL, "IMM", "TB-IMM",
				ORANGE, false));
		}

		// Prayer lock
		int prayerLockTicks = self.getPrayerLockTicksRemaining(tick);
		if (prayerLockTicks > 0)
		{
			out.add(new StatusSlot("plock", StatusPriority.CRITICAL,
				String.valueOf(prayerLockTicks), "PLOCK " + prayerLockTicks, RED, false));
		}

		// Corruption — parent + secondary (next drain tick)
		if (fx.isCorruptionActive())
		{
			int iters = fx.getCorruptionIterationsRemaining();
			int total = fx.getCorruptionTotalTicks(tick);
			String label     = total > 0 ? ticksToMSS(total) : iters + "x";
			String textLabel = "CORRUPT " + label;
			out.add(new StatusSlot("corrupt", StatusPriority.CRITICAL, label, textLabel, RED, false));

			int nextDrain = fx.getCorruptionNextDrainTicks(tick);
			if (nextDrain > 0)
			{
				String sec = "-" + fx.getCorruptionBaseDamage() + " " + nextDrain + "t";
				out.add(new StatusSlot("corrupt_next", StatusPriority.CRITICAL, sec,
					"NXDRAIN " + sec, RED, true));
			}
		}

		// ── TACTICAL ─────────────────────────────────────────────────────────
		// Venom takes priority over poison
		if (poison.isVenomed())
			out.add(new StatusSlot("venom", StatusPriority.TACTICAL, "", "VENOM", TOXIC_GREEN, false));
		else if (poison.isPoisoned())
			out.add(new StatusSlot("poison", StatusPriority.TACTICAL, "", "POISON", TOXIC_GREEN, false));

		// Burn — parent + secondary (next hit)
		if (fx.getBurnDamageTotal() > 0)
		{
			out.add(new StatusSlot("burn", StatusPriority.TACTICAL,
				String.valueOf(fx.getBurnDamageTotal()),
				"BURN " + fx.getBurnDamageTotal(), RED, false));
			if (fx.getBurnDamageNextHit() > 0)
			{
				out.add(new StatusSlot("burn_next", StatusPriority.TACTICAL,
					"BURN+" + fx.getBurnDamageNextHit(),
					"BURN NXT " + fx.getBurnDamageNextHit(), RED, true));
			}
		}

		// Staff of the Dead melee protection
		int sotdTicks = fx.getStaffProtTicks(tick);
		if (sotdTicks > 0)
			addTimed(out, "sotd", StatusPriority.TACTICAL, "SOTD", sotdTicks, false);

		// Ward of Arceuus ↔ Ward CD: lifecycle slot
		int wardTicks = fx.getWardOfArceuusTicks(tick);
		if (wardTicks > 0)
			addTimed(out, "ward", StatusPriority.TACTICAL, "WARD", wardTicks, false);
		else
		{
			int wardCd = fx.getWardCooldownTicks(tick);
			if (wardCd > 0)
				addTimed(out, "ward_cd", StatusPriority.TACTICAL, "WARD-CD", wardCd, false);
		}

		// Mark of Darkness ↔ Mark CD: lifecycle slot
		int markTicks = fx.getMarkOfDarknessTicks(tick);
		if (markTicks > 0)
			addTimed(out, "mark", StatusPriority.TACTICAL, "MARK", markTicks, false);
		else
		{
			int markCd = fx.getMarkCooldownTicks(tick);
			if (markCd > 0)
				addTimed(out, "mark_cd", StatusPriority.TACTICAL, "MARK-CD", markCd, false);
		}

		// ── SUSTAIN ───────────────────────────────────────────────────────────
		// Anti-venom takes priority over anti-poison
		if (poison.isAntiVenomActive())
			addTimed(out, "anti_venom", StatusPriority.SUSTAIN, "ANTI-V",
				poison.getImmunityTicksRemaining(tick), false);
		else if (poison.isAntiPoisonActive())
			addTimed(out, "anti_poison", StatusPriority.SUSTAIN, "ANTI-P",
				poison.getImmunityTicksRemaining(tick), false);

		// Divine potions
		if (showAll || config.showDivineTimers())
		{
			addTimed(out, "dsc", StatusPriority.SUSTAIN, "DSC", fx.getDivineSupercombatTicks(), false);
			addTimed(out, "drg", StatusPriority.SUSTAIN, "DRG", fx.getDivineRangingTicks(),     false);
			addTimed(out, "dmg", StatusPriority.SUSTAIN, "DMG", fx.getDivineMagicTicks(),       false);
			addTimed(out, "bas", StatusPriority.SUSTAIN, "BAS", fx.getDivineBastionTicks(),     false);
			addTimed(out, "btm", StatusPriority.SUSTAIN, "BTM", fx.getDivineBattlemageTicks(),  false);
			addTimed(out, "dsa", StatusPriority.SUSTAIN, "DSA", fx.getDivineSuperAttackTicks(),   false);
			addTimed(out, "dss", StatusPriority.SUSTAIN, "DSS", fx.getDivineSuperStrengthTicks(), false);
			addTimed(out, "dsd", StatusPriority.SUSTAIN, "DSD", fx.getDivineSuperDefenceTicks(),  false);

			// Menaphite Remedy — parent + secondary (next proc)
			if (fx.getMenaphite().isActive())
			{
				addTimed(out, "menaphite", StatusPriority.SUSTAIN, "MEN",
					fx.getMenaphite().getTotalTicksRemaining(), false);
				if (fx.getMenaphite().isNextProcKnown())
					addTimedPeriodic(out, "menaphite_next", StatusPriority.SUSTAIN, "NXT",
						fx.getMenaphite().getNextProcTicks(), true);
			}
		}

		// Prayer Regeneration potion — parent + secondary (next proc)
		if (fx.getPrayerRegen().isActive())
		{
			addTimed(out, "prayer_regen", StatusPriority.SUSTAIN, "PRYR",
				fx.getPrayerRegen().getTotalTicksRemaining(), false);
			if (fx.getPrayerRegen().isNextProcKnown())
				addTimedPeriodic(out, "prayer_regen_next", StatusPriority.SUSTAIN, "P-NXT",
					fx.getPrayerRegen().getNextProcTicks(), true);
		}

		// Stamina potion
		if (fx.getStaminaEffectTicks() > 0)
			addTimed(out, "stamina", StatusPriority.SUSTAIN, "STAM", fx.getStaminaEffectTicks(), false);

		// Antifire
		int afTicks  = fx.getAntifireTicks(tick);
		int safTicks = fx.getSuperAntifireTicks(tick);
		if (afTicks  > 0) addTimed(out, "af",  StatusPriority.SUSTAIN, "AF",  afTicks,  false);
		if (safTicks > 0) addTimed(out, "saf", StatusPriority.SUSTAIN, "SAF", safTicks, false);

		// ── READINESS ─────────────────────────────────────────────────────────
		if (fx.getImbuedHeartCooldownTicks() > 0)
			addTimed(out, "ih_cd", StatusPriority.READINESS, "IH-CD",
				fx.getImbuedHeartCooldownTicks(), false);

		int surgeTicks = fx.getSurgePotionTicks(tick);
		if (surgeTicks > 0)
			addTimed(out, "surge", StatusPriority.READINESS, "SURGE", surgeTicks, false);

		return out;
	}

	// ── Private helpers ───────────────────────────────────────────────────────

	private static void addTimed(List<StatusSlot> out, String slotId, StatusPriority priority,
		String prefix, int ticks, boolean isSecondary)
	{
		if (ticks <= 0) return;
		String t         = ticksToMSS(ticks);
		String textLabel = prefix + " " + t;
		out.add(new StatusSlot(slotId, priority, t, textLabel, timerColor(ticks), isSecondary));
	}

	/** Like {@link #addTimed} but emits at ticks=0 as "0t" — used for known cycle boundaries. */
	private static void addTimedPeriodic(List<StatusSlot> out, String slotId, StatusPriority priority,
		String prefix, int ticks, boolean isSecondary)
	{
		String t         = ticks <= 0 ? "0t" : ticksToMSS(ticks);
		String textLabel = prefix + " " + t;
		out.add(new StatusSlot(slotId, priority, t, textLabel, timerColor(ticks), isSecondary));
	}

	private static String freezeSlotId(int spriteId)
	{
		switch (spriteId)
		{
			case SpriteID.SPELL_ICE_RUSH:    return "freeze_rush";
			case SpriteID.SPELL_ICE_BURST:   return "freeze_burst";
			case SpriteID.SPELL_ICE_BLITZ:   return "freeze_blitz";
			case SpriteID.SPELL_ICE_BARRAGE: return "freeze_barrage";
			default:                         return "freeze_barrage";
		}
	}

	// ── Format helpers (package-private for tests) ────────────────────────────

	/**
	 * Formats a freeze countdown: ticks ≤ 3 show as "3t"/"2t"/"1t" for tick-accurate
	 * precision at the end of the timer; otherwise converts to seconds.
	 * Package-private for tests.
	 */
	static String formatFreezeRemaining(int ticks)
	{
		return ticks <= 3 ? ticks + "t" : ticksToSecs(ticks);
	}

	static String ticksToSecs(int ticks)
	{
		return (int) Math.round(ticks * 0.6) + "s";
	}

	static String ticksToMSS(int ticks)
	{
		int s = ticks * 600 / 1000;
		return (s / 60) + ":" + String.format("%02d", s % 60);
	}

	static Color timerColor(int ticks)
	{
		int s = ticks * 600 / 1000;
		return s > 60 ? GREEN : s > 30 ? YELLOW : RED;
	}
}

package com.pvphud;

import java.awt.Color;

/** Immutable semantic projection unit. One slot per visible effect row in the HUD. */
public final class StatusSlot
{
	/**
	 * Stable identifier used by {@link PvpHudOverlay#getIconFor} to resolve the effect icon.
	 * Also used as a diagnostic key in tests and manifests.
	 */
	public final String         slotId;
	public final StatusPriority priority;

	/** Short label for icon-assisted modes (VERTICAL_BAR, ICON_TRAY). e.g. "1:42", "12s". */
	public final String         label;

	/**
	 * Full label for TEXT mode where no icon provides context. e.g. "DSC 1:42", "ICE 12s".
	 * {@code null} means TEXT mode falls back to {@link #label}.
	 */
	public final String         textLabel;

	/** Colour applied to the label text and any placeholder icon box. */
	public final Color          color;

	/** Optional highlight border colour for the icon cell. {@code null} = no highlight. */
	public final Color          highlightColor;

	/**
	 * True for compound sub-entries (e.g. "next proc" or "next hit" lines).
	 * ICON_TRAY and 2-col renderers skip secondary entries; TEXT and VERTICAL_BAR show them.
	 */
	public final boolean        isSecondary;

	public StatusSlot(String slotId, StatusPriority priority, String label, String textLabel,
		Color color, Color highlightColor, boolean isSecondary)
	{
		this.slotId         = slotId;
		this.priority       = priority;
		this.label          = label;
		this.textLabel      = textLabel;
		this.color          = color;
		this.highlightColor = highlightColor;
		this.isSecondary    = isSecondary;
	}

	public StatusSlot(String slotId, StatusPriority priority, String label, String textLabel,
		Color color, boolean isSecondary)
	{
		this(slotId, priority, label, textLabel, color, null, isSecondary);
	}

	/** Returns the label to use in TEXT mode. */
	public String getTextLabel()
	{
		return textLabel != null ? textLabel : label;
	}
}

package com.pvphud.state;

import lombok.Getter;

/**
 * Local-player action timing state, using absolute game-tick deadlines.
 *
 * All "remaining ticks" values are derived on demand as (deadline - currentTick),
 * clamped to zero for display.  The deadlines themselves are never clamped —
 * this preserves "idle attack credit" so that food consumed after a long idle
 * period correctly leaves the attack clock ready.
 *
 * Three independent consumption channels mirror OSRS server mechanics:
 *   foodReadyTick       — regular food (shark, brew, dark crab …)
 *   comboFoodReadyTick  — karambwan / combo-food channel
 *   potionReadyTick     — all potions
 *
 * GameTick handlers must NOT decrement these values — that was the old model.
 * Read remaining ticks through the currentTick-parameterised getters.
 */
public class ActionClockState
{
	/** Sentinel: deadline has never been set for this channel. */
	public static final long NEVER = Long.MIN_VALUE;

	/** Absolute tick when the player may next attack. NEVER = has not attacked. */
	private long attackReadyTick = NEVER;

	/** Speed (ticks) used for the last confirmed attack; 0 = no attack recorded. */
	@Getter private int lastWeaponSpeedTicks;

	/** Absolute tick when the regular food channel unblocks. */
	private long foodReadyTick = NEVER;

	/** Absolute tick when the combo-food (karambwan) channel unblocks. */
	private long comboFoodReadyTick = NEVER;

	/** Absolute tick when the potion channel unblocks. */
	private long potionReadyTick = NEVER;

	// ── Attack ────────────────────────────────────────────────────────────────

	/** True once an attack has been confirmed (attackReadyTick is meaningful). */
	public boolean hasAttacked()
	{
		return attackReadyTick != NEVER;
	}

	/**
	 * Remaining ticks until the player may attack again.
	 * Returns 0 (ready) when the deadline is in the past — the deadline itself
	 * is NOT clamped so food interaction remains correct.
	 */
	public int getAttackDelayTicks(long currentTick)
	{
		if (attackReadyTick == NEVER) return 0;
		return (int) Math.max(0L, attackReadyTick - currentTick);
	}

	/**
	 * Records a confirmed attack.  Sets attackReadyTick = currentTick + speed.
	 * Only advances the deadline; a new attack cannot shorten an already-running
	 * delay from a previous attack on the same or earlier tick.
	 */
	public void setAttack(long currentTick, int speed)
	{
		long candidate = currentTick + speed;
		if (attackReadyTick == NEVER || candidate > attackReadyTick)
		{
			attackReadyTick       = candidate;
			lastWeaponSpeedTicks  = speed;
		}
	}

	/**
	 * ADDITIVELY adds attackDelay to the existing attack deadline.
	 *
	 * This is the critical food-interaction rule:
	 *   attackReadyTick += delay
	 * NOT:
	 *   attackReadyTick = currentTick + delay
	 *
	 * Example: attackReadyTick was tick 100, currentTick is 105 (ATK ready).
	 * Eating normal food (+3): attackReadyTick becomes 103. ATK remains ready.
	 *
	 * Example: attackReadyTick was tick 108, currentTick is 105 (3 ticks left).
	 * Eating normal food (+3): attackReadyTick becomes 111. ATK shows 6 ticks.
	 *
	 * No-op when the player has never attacked (attackReadyTick == NEVER).
	 */
	public void addFoodAttackDelay(int delay)
	{
		if (attackReadyTick != NEVER)
			attackReadyTick += delay;
	}

	// ── Food channel ──────────────────────────────────────────────────────────

	/** Remaining ticks before regular food can be eaten again (0 = ready). */
	public int getEatCooldownTicks(long currentTick)
	{
		if (foodReadyTick == NEVER) return 0;
		return (int) Math.max(0L, foodReadyTick - currentTick);
	}

	/** Remaining ticks before combo food (karambwan) can be eaten again (0 = ready). */
	public int getComboEatCooldownTicks(long currentTick)
	{
		if (comboFoodReadyTick == NEVER) return 0;
		return (int) Math.max(0L, comboFoodReadyTick - currentTick);
	}

	// ── Potion channel ────────────────────────────────────────────────────────

	/** Remaining ticks before a potion can be drunk again (0 = ready). */
	public int getPotCooldownTicks(long currentTick)
	{
		if (potionReadyTick == NEVER) return 0;
		return (int) Math.max(0L, potionReadyTick - currentTick);
	}

	// ── Consumable application ────────────────────────────────────────────────

	/**
	 * Applies all cooldown effects for a confirmed consumable.
	 *
	 * Channels are set to max(existing, currentTick + lock) so that same-tick
	 * combo eating accumulates correctly regardless of event order.
	 * attackReadyTick is modified additively via addFoodAttackDelay.
	 */
	public void applyConsumable(long currentTick, com.pvphud.ConsumableType type)
	{
		if (!type.isKnown()) return;

		addFoodAttackDelay(type.attackDelay);

		if (type.eatLock > 0)
		{
			long candidate = currentTick + type.eatLock;
			if (foodReadyTick == NEVER || candidate > foodReadyTick)
				foodReadyTick = candidate;
		}
		if (type.comboLock > 0)
		{
			long candidate = currentTick + type.comboLock;
			if (comboFoodReadyTick == NEVER || candidate > comboFoodReadyTick)
				comboFoodReadyTick = candidate;
		}
		if (type.potLock > 0)
		{
			long candidate = currentTick + type.potLock;
			if (potionReadyTick == NEVER || candidate > potionReadyTick)
				potionReadyTick = candidate;
		}
	}

	// ── Convenience readiness predicates ──────────────────────────────────────

	public boolean isAttackReady(long currentTick) { return getAttackDelayTicks(currentTick) <= 0; }
	public boolean isEatReady(long currentTick)    { return getEatCooldownTicks(currentTick) <= 0; }
	public boolean isPotReady(long currentTick)    { return getPotCooldownTicks(currentTick) <= 0; }

	// ── Debug / test initialisation ──────────────────────────────────────────────

	/**
	 * For debug/testing: sets attack state as if an attack happened with the given
	 * weapon speed and {@code ticks} ticks still remaining until ready.
	 */
	public void forceAttackDelay(long currentTick, int ticks, int weaponSpeed)
	{
		if (weaponSpeed > 0)
		{
			attackReadyTick      = currentTick + ticks;
			lastWeaponSpeedTicks = weaponSpeed;
		}
	}

	/** For debug/testing: sets eat cooldown ticks remaining directly. */
	public void forceEatCooldown(long currentTick, int ticks)
	{
		foodReadyTick = ticks > 0 ? currentTick + ticks : NEVER;
	}

	/** For debug/testing: sets pot cooldown ticks remaining directly. */
	public void forcePotCooldown(long currentTick, int ticks)
	{
		potionReadyTick = ticks > 0 ? currentTick + ticks : NEVER;
	}

	// ── Reset ──────────────────────────────────────────────────────────────────

	public void reset()
	{
		attackReadyTick     = NEVER;
		lastWeaponSpeedTicks = 0;
		foodReadyTick       = NEVER;
		comboFoodReadyTick  = NEVER;
		potionReadyTick     = NEVER;
	}
}

package com.pvphud.state;

/**
 * Groups all damage hitsplats from a single game tick into one record.
 * Outgoing = damage we dealt (isMine() hitsplats on opponent).
 * Incoming = damage we received during an active session.
 *
 * Up to MAX_STORED individual hit values are retained per direction;
 * additional hits still accumulate into the totals.
 */
public class DamageExchange
{
	private static final int MAX_STORED = 2;

	private final int tick;

	private int outgoingTotal;
	private int outgoingHitCount;
	private final int[] outgoingHits = new int[MAX_STORED];
	private int outgoingPrayerDrain;

	private int incomingTotal;
	private int incomingHitCount;
	private final int[] incomingHits = new int[MAX_STORED];

	public DamageExchange(int tick)
	{
		this.tick = tick;
	}

	public void addOutgoing(int damage, int prayerDrain)
	{
		outgoingTotal       += damage;
		outgoingPrayerDrain += prayerDrain;
		if (outgoingHitCount < MAX_STORED)
			outgoingHits[outgoingHitCount] = damage;
		outgoingHitCount++;
	}

	public void addIncoming(int damage)
	{
		incomingTotal += damage;
		if (incomingHitCount < MAX_STORED)
			incomingHits[incomingHitCount] = damage;
		incomingHitCount++;
	}

	public int getTick()                 { return tick; }
	public int getOutgoingTotal()        { return outgoingTotal; }
	public int getOutgoingHitCount()     { return outgoingHitCount; }
	public int getOutgoingPrayerDrain()  { return outgoingPrayerDrain; }
	public int getIncomingTotal()        { return incomingTotal; }
	public int getIncomingHitCount()     { return incomingHitCount; }

	public boolean hasOutgoing() { return outgoingHitCount > 0; }
	public boolean hasIncoming() { return incomingHitCount > 0; }

	public int getOutgoingHit(int index)
	{
		if (index < 0 || index >= outgoingHitCount || index >= MAX_STORED) return 0;
		return outgoingHits[index];
	}

	public int getIncomingHit(int index)
	{
		if (index < 0 || index >= incomingHitCount || index >= MAX_STORED) return 0;
		return incomingHits[index];
	}
}

package com.pvphud.state;

import lombok.Getter;
import lombok.Setter;

/** Miscellaneous self-effects: spec energy and timed potion effects. */
public class EffectState
{
	/** Special attack energy 0–100. */
	@Getter @Setter private int specEnergy;

	/** Stamina potion effect ticks remaining (self-tracked; server flag is binary). */
	@Getter @Setter private int staminaEffectTicks;

	// ── Divine potion remaining ticks (varbit counts down each game tick) ──────
	@Getter @Setter private int divineSupercombatTicks;
	@Getter @Setter private int divineRangingTicks;
	@Getter @Setter private int divineMagicTicks;
	@Getter @Setter private int divineBastionTicks;
	@Getter @Setter private int divineBattlemageTicks;
	@Getter @Setter private int divineSuperAttackTicks;
	@Getter @Setter private int divineSuperStrengthTicks;
	@Getter @Setter private int divineSuperDefenceTicks;

	/** Imbued Heart recharge cooldown — varbit counts down from ~800 ticks (8 min). */
	@Getter @Setter private int imbuedHeartCooldownTicks;

	// ── Prayer Regeneration potion — periodic effect ──────────────────────────
	// totalTicksRemaining = Varbits.BUFF_PRAYER_REGENERATION × 12 (updated from varbit).
	// nextProcTicks       = 12 (reset each time the varbit decrements).
	@Getter private final PeriodicEffect prayerRegen = new PeriodicEffect();
	private int prevPrayerRegenVarbit = -1;

	/**
	 * Called from onVarbitChanged(BUFF_PRAYER_REGENERATION).
	 * Sets total remaining and resets next-proc on each varbit decrement.
	 */
	public void updatePrayerRegen(int varbitValue)
	{
		prayerRegen.setTotalTicksRemaining(varbitValue * 12);
		if (varbitValue == 0)
		{
			prayerRegen.reset();
		}
		else if (prevPrayerRegenVarbit > 0 && varbitValue < prevPrayerRegenVarbit)
		{
			prayerRegen.setNextProcTicks(12);
		}
		prevPrayerRegenVarbit = varbitValue;
	}

	// ── Staff of the Dead / Toxic SotD / Staff of Light / Staff of Balance ────
	// 100-tick (60-second) melee damage reduction buff applied by the weapon special.
	// Detected via GAMEMESSAGE; cleared on weapon unequip or expiry message.
	private int staffProtEndTick = -1;

	public int getStaffProtTicks(int currentTick)
	{
		return staffProtEndTick < 0 ? 0 : Math.max(0, staffProtEndTick - currentTick);
	}

	public void applyStaffProt(int currentTick) { staffProtEndTick = currentTick + 100; }
	public void clearStaffProt()                { staffProtEndTick = -1; }

	// ── Surge potion cooldown ─────────────────────────────────────────────────
	// VarbitID.SURGE_POTION_TIMER × 10 = ticks remaining on the cooldown.
	private int surgePotionEndTick = -1;

	public int getSurgePotionTicks(int currentTick)
	{
		return surgePotionEndTick < 0 ? 0 : Math.max(0, surgePotionEndTick - currentTick);
	}

	/** Called from onVarbitChanged(SURGE_POTION_TIMER). */
	public void updateSurgePotionFromVarbit(int varbitValue, int currentTick)
	{
		if (varbitValue <= 0)
			surgePotionEndTick = -1;
		else
			surgePotionEndTick = currentTick + varbitValue * 10;
	}

	// ── Burn damage counters ──────────────────────────────────────────────────
	// VarbitID.PLAYER_OWN_BURN_DAMAGE_TOTAL         = accumulated burn damage so far.
	// VarbitID.PLAYER_OWN_BURN_DAMAGE_HITSPLAT_SIZE = next burn hit size.
	@Getter @Setter private int burnDamageTotal;
	@Getter @Setter private int burnDamageNextHit;

	// ── Corruption ────────────────────────────────────────────────────────────
	// VarbitID.CORRUPTION_TARGET_ITERATIONS  = total number of prayer drains.
	// VarbitID.CORRUPTION_CURRENT_ITERATIONS = drains completed so far (counts up).
	// VarbitID.CORRUPTION_BASE_DAMAGE        = prayer drained per iteration.
	//
	// Interval detection: when CORRUPTION_CURRENT_ITERATIONS increments we record
	// the tick and compute interval from two successive increments.  Until two
	// increments are observed the interval is unknown (0).
	@Getter @Setter private int corruptionTargetIterations;
	@Getter @Setter private int corruptionCurrentIterations;
	@Getter @Setter private int corruptionBaseDamage;
	private int corruptionLastIterationTick = -1;
	private int corruptionDetectedInterval;
	private int corruptionNextDrainTick = -1;

	public boolean isCorruptionActive()
	{
		return corruptionTargetIterations > 0 && corruptionCurrentIterations < corruptionTargetIterations;
	}

	public int getCorruptionIterationsRemaining()
	{
		return Math.max(0, corruptionTargetIterations - corruptionCurrentIterations);
	}

	/**
	 * Remaining Corruption ticks, or 0 if the interval has not yet been observed.
	 * Formula: (nextDrainTick − currentTick) + (remainingIterations − 1) × interval
	 */
	public int getCorruptionTotalTicks(int currentTick)
	{
		if (corruptionDetectedInterval <= 0 || corruptionNextDrainTick < 0) return 0;
		int remaining = getCorruptionIterationsRemaining();
		if (remaining == 0) return 0;
		return Math.max(0, corruptionNextDrainTick - currentTick) + (remaining - 1) * corruptionDetectedInterval;
	}

	/** Ticks until the next Corruption prayer drain, or 0 if interval unknown. */
	public int getCorruptionNextDrainTicks(int currentTick)
	{
		return corruptionNextDrainTick < 0 ? 0 : Math.max(0, corruptionNextDrainTick - currentTick);
	}

	/**
	 * Called when CORRUPTION_CURRENT_ITERATIONS changes.
	 * Detects drain interval from two successive increments.
	 */
	public void onCorruptionIterationChanged(int currentTick)
	{
		if (corruptionLastIterationTick >= 0)
		{
			corruptionDetectedInterval = currentTick - corruptionLastIterationTick;
			corruptionNextDrainTick    = currentTick + corruptionDetectedInterval;
		}
		corruptionLastIterationTick = currentTick;
	}

	/** Clear all Corruption state (iterations consumed, expired, or plugin restart). */
	public void clearCorruption()
	{
		corruptionTargetIterations  = 0;
		corruptionCurrentIterations = 0;
		corruptionBaseDamage        = 0;
		corruptionLastIterationTick = -1;
		corruptionDetectedInterval  = 0;
		corruptionNextDrainTick     = -1;
	}

	// ── Ward of Arceuus ───────────────────────────────────────────────────────
	// Active buff: magicLevel ticks (detected via GAMEMESSAGE).
	// Cooldown:    Varbits.WARD_OF_ARCEUUS_COOLDOWN fires 1 when cooldown starts;
	//              fixed 50-tick (30-second) cooldown.
	private int wardOfArceuusEndTick  = -1;
	private int wardCooldownEndTick   = -1;

	public int getWardOfArceuusTicks(int currentTick)
	{
		return wardOfArceuusEndTick < 0 ? 0 : Math.max(0, wardOfArceuusEndTick - currentTick);
	}

	public void applyWardOfArceuus(int currentTick, int magicLevel)
	{
		wardOfArceuusEndTick = currentTick + magicLevel;
	}

	public void clearWardOfArceuus() { wardOfArceuusEndTick = -1; }

	public int getWardCooldownTicks(int currentTick)
	{
		return wardCooldownEndTick < 0 ? 0 : Math.max(0, wardCooldownEndTick - currentTick);
	}

	/** Fixed 50-tick (30-second) cooldown starts when the ward activates. */
	public void applyWardCooldown(int currentTick) { wardCooldownEndTick = currentTick + 50; }
	public void clearWardCooldown()                { wardCooldownEndTick = -1; }

	// ── Mark of Darkness ─────────────────────────────────────────────────────
	// Active buff: magicLevel × 3 ticks (detected via GAMEMESSAGE).
	// Cooldown:    VarbitID.BUFF_MARK_OF_DARKNESS_DISABLED fires 1 when active;
	//              fixed 10-tick cooldown.
	private int markOfDarknessEndTick = -1;
	private int markCooldownEndTick   = -1;

	public int getMarkOfDarknessTicks(int currentTick)
	{
		return markOfDarknessEndTick < 0 ? 0 : Math.max(0, markOfDarknessEndTick - currentTick);
	}

	public void applyMarkOfDarkness(int currentTick, int magicLevel)
	{
		markOfDarknessEndTick = currentTick + magicLevel * 3;
	}

	public void clearMarkOfDarkness() { markOfDarknessEndTick = -1; }

	public int getMarkCooldownTicks(int currentTick)
	{
		return markCooldownEndTick < 0 ? 0 : Math.max(0, markCooldownEndTick - currentTick);
	}

	/** Fixed 10-tick cooldown. */
	public void applyMarkCooldown(int currentTick) { markCooldownEndTick = currentTick + 10; }
	public void clearMarkCooldown()                { markCooldownEndTick = -1; }

	// ── Menaphite Remedy — periodic effect ───────────────────────────────────
	// totalTicksRemaining is updated from the server varbit each tick.
	// nextProcTicks is reset to 25 each time the varbit decrements (see onVarbitChanged).
	@Getter private final PeriodicEffect menaphite = new PeriodicEffect();

	// ── Antifire protection — phase-based duration tracking ──────────────────
	// Two independent families; phase intervals differ between them.
	//
	// Normal family (Antifire + Extended Antifire): Varbits.ANTIFIRE, 30 ticks/phase
	//   Fresh Antifire:          varbit 20  → 600 ticks
	//   Fresh Extended Antifire: varbit 40  → 1200 ticks
	//
	// Super family (Super Antifire + Extended Super Antifire): Varbits.SUPER_ANTIFIRE, 20 ticks/phase
	//   Fresh Super Antifire:          varbit 15 → 300 ticks
	//   Fresh Extended Super Antifire: varbit 30 → 600 ticks
	//
	// nextAntifireTick / nextSuperAntifireTick:
	//   The game tick at which the next phase boundary occurs.
	//   -1 = effect not active (or phase not yet observed).
	//   Set to (currentTick + phaseInterval) when the effect starts or when the
	//   plugin joins mid-effect (conservative: assumes full interval remaining).
	//   Only updated when the phase boundary has passed (nextTick - currentTick <= 0).
	//
	// Remaining ticks formula (mirrors RuneLite TimersAndBuffsPlugin):
	//   nextXxxTick - currentTick + (varbitValue - 1) * phaseInterval
	private int nextAntifireTick        = -1;
	private int antifireVarbitValue;
	private int nextSuperAntifireTick   = -1;
	private int superAntifireVarbitValue;

	public int  getNextAntifireTick()           { return nextAntifireTick; }
	public void setNextAntifireTick(int t)       { nextAntifireTick = t; }
	public int  getAntifireVarbitValue()         { return antifireVarbitValue; }
	public void setAntifireVarbitValue(int v)    { antifireVarbitValue = v; }
	public int  getNextSuperAntifireTick()       { return nextSuperAntifireTick; }
	public void setNextSuperAntifireTick(int t)  { nextSuperAntifireTick = t; }
	public int  getSuperAntifireVarbitValue()    { return superAntifireVarbitValue; }
	public void setSuperAntifireVarbitValue(int v) { superAntifireVarbitValue = v; }

	/** Remaining normal-antifire ticks (0 if not active). */
	public int getAntifireTicks(int currentTick)
	{
		if (nextAntifireTick < 0 || antifireVarbitValue <= 0) return 0;
		return Math.max(0, nextAntifireTick - currentTick + (antifireVarbitValue - 1) * 30);
	}

	/** Remaining super-antifire ticks (0 if not active). */
	public int getSuperAntifireTicks(int currentTick)
	{
		if (nextSuperAntifireTick < 0 || superAntifireVarbitValue <= 0) return 0;
		return Math.max(0, nextSuperAntifireTick - currentTick + (superAntifireVarbitValue - 1) * 20);
	}

	public void reset()
	{
		specEnergy               = 0;
		staminaEffectTicks       = 0;
		divineSupercombatTicks   = 0;
		divineRangingTicks       = 0;
		divineMagicTicks         = 0;
		divineBastionTicks       = 0;
		divineBattlemageTicks    = 0;
		divineSuperAttackTicks   = 0;
		divineSuperStrengthTicks = 0;
		divineSuperDefenceTicks  = 0;
		imbuedHeartCooldownTicks = 0;
		prayerRegen.reset();
		prevPrayerRegenVarbit    = -1;
		staffProtEndTick         = -1;
		surgePotionEndTick       = -1;
		burnDamageTotal          = 0;
		burnDamageNextHit        = 0;
		clearCorruption();
		wardOfArceuusEndTick     = -1;
		wardCooldownEndTick      = -1;
		markOfDarknessEndTick    = -1;
		markCooldownEndTick      = -1;
		menaphite.reset();
		nextAntifireTick         = -1;
		antifireVarbitValue      = 0;
		nextSuperAntifireTick    = -1;
		superAntifireVarbitValue = 0;
	}
}

