package com.pvphud.state;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Getter;

/**
 * Lifecycle-managed snapshot of a single PvP encounter.
 *
 * A session is confirmed and begun when one of the following happens while a
 * candidate opponent is being tracked:
 *   - the local player uses the Attack menu option on a valid attackable player, or
 *   - a confirmed outgoing hitsplat (hitsplat.isMine()) lands on the candidate, or
 *   - an incoming hitsplat lands on the local player while the candidate is
 *     currently interacting with the local player.
 *
 * Simply following/targeting a player does not populate the opponent panel —
 * the session is only materialised once combat is confirmed by one of the
 * triggers above.
 *
 * Once active, the session survives brief InteractingChanged nulls (movement,
 * targeting flickers) and short opponent despawn/reappear windows (grace of
 * {@code OPPONENT_GRACE_TICKS} game ticks). It terminates on:
 *   - Opponent death (HP ratio → 0 via pollOpponentHealth)
 *   - Local player death (HP → 0)
 *   - No combat in either direction for {@code TIMEOUT_TICKS} game ticks
 *   - Opponent remaining despawned beyond the grace window
 *   - Logout or world hop (fullReset)
 *   - Explicit eviction (plugin shutdown)
 *
 * Fight totals and the exchange buffer live here so they are not wiped by
 * transient InteractingChanged events.
 */
public class PvpFightSession
{
	/** Ticks with no combat in either direction before the session self-expires. ~30 s. */
	private static final int TIMEOUT_TICKS = 50;
	private static final int MAX_EXCHANGES = 6;

	@Getter private final String opponentName;
	@Getter private final int    startTick;
	@Getter private int          lastCombatTick;

	/** Total damage this player dealt to the opponent this session. */
	@Getter private int totalOutgoing;
	/** Total damage this player received this session. */
	@Getter private int totalIncoming;

	/** True once terminate() has been called; immutable after that. */
	@Getter private boolean terminated;

	/** Tick-keyed exchange records, newest first, capped at MAX_EXCHANGES. */
	private final ArrayDeque<DamageExchange> exchanges = new ArrayDeque<>(MAX_EXCHANGES);

	public PvpFightSession(String opponentName, int startTick)
	{
		this.opponentName   = opponentName;
		this.startTick      = startTick;
		this.lastCombatTick = startTick;
	}

	/**
	 * Records an owned outgoing hit. Only call when hitsplat.isMine() is true.
	 * Updates session totals and the exchange buffer for {@code currentTick}.
	 */
	public void onOutgoingHit(int damage, int prayerDrain, int currentTick)
	{
		lastCombatTick = currentTick;
		totalOutgoing  += damage;
		getOrCreate(currentTick).addOutgoing(damage, prayerDrain);
	}

	/**
	 * Records an incoming hit on the local player during an active session.
	 */
	public void onIncomingHit(int damage, int currentTick)
	{
		lastCombatTick = currentTick;
		totalIncoming  += damage;
		getOrCreate(currentTick).addIncoming(damage);
	}

	/**
	 * Marks combat activity without recording damage — used for 0-splats that
	 * confirm ongoing engagement without contributing to session totals.
	 */
	public void touchCombat(int currentTick)
	{
		lastCombatTick = currentTick;
	}

	private DamageExchange getOrCreate(int tick)
	{
		DamageExchange head = exchanges.peekFirst();
		if (head != null && head.getTick() == tick) return head;
		if (exchanges.size() >= MAX_EXCHANGES) exchanges.pollLast();
		DamageExchange ex = new DamageExchange(tick);
		exchanges.addFirst(ex);
		return ex;
	}

	/** Recent exchanges newest-first; never null. */
	public List<DamageExchange> getRecentExchanges()
	{
		return Collections.unmodifiableList(new ArrayList<>(exchanges));
	}

	/** Returns the exchange record for {@code tick}, or null if none exists. */
	public DamageExchange getExchangeForTick(int tick)
	{
		for (DamageExchange ex : exchanges)
			if (ex.getTick() == tick) return ex;
		return null;
	}

	/**
	 * True when no combat has occurred for TIMEOUT_TICKS and the session has
	 * not been explicitly terminated. Checked each game tick by the plugin.
	 */
	public boolean isStale(int currentTick)
	{
		return !terminated && (currentTick - lastCombatTick) >= TIMEOUT_TICKS;
	}

	/** Permanently close this session. Safe to call multiple times. */
	public void terminate()
	{
		terminated = true;
	}
}

package com.pvphud.state;

import lombok.Getter;
import lombok.Setter;

/** Local-player self state: freeze, teleblock, prayer-lock, HP/Prayer, ammo. */
public class SelfState
{
	/**
	 * Game tick on which the freeze started (-1 = not frozen).
	 * Stored as a start/end tick pair so repeated ice impacts cannot extend it.
	 */
	@Getter private int freezeStartTick = -1;

	/** Game tick on which the freeze expires (-1 = not frozen). */
	private int freezeEndTick = -1;

	/** SpriteID of the spell that froze the player (0 = unknown / not frozen). */
	@Getter @Setter private int freezeSpriteId;

	/** Post-thaw ticks during which the player cannot be refrozen (OSRS mechanic). */
	public static final int REFREEZE_IMMUNITY_TICKS = 5;

	/**
	 * Game tick when post-thaw refreeze immunity expires (-1 = not immune).
	 * Set to (currentTick + REFREEZE_IMMUNITY_TICKS) by {@link #expireFreeze(int)}.
	 */
	private int refreezeImmunityEndTick = -1;

	/** Ticks remaining on the local player's Tele Block (0 = not TB'd). */
	@Getter @Setter private int teleBlockTicksRemaining;

	/** True when in the post-TB reapplication immunity window (raw varbit 1–100). */
	@Getter @Setter private boolean tbImmunityActive;

	/**
	 * Game tick when Dragon scimitar Sever's protection-prayer lock expires (-1 = not locked).
	 * Duration: 8 ticks.
	 */
	private int prayerLockEndTick = -1;

	@Getter @Setter private int currentHp;
	@Getter @Setter private int maxHp;
	@Getter @Setter private int currentPrayer;
	@Getter @Setter private int maxPrayer;

	/** Wall-clock ms of the last positive incoming damage; -1 = none yet. Used for HP bar shake. */
	@Getter @Setter private long lastIncomingDamageMs = -1;

	/** Damage amount of the last incoming hit; 0 = none. Used for transient splat display. */
	@Getter @Setter private int lastIncomingDamage;

	/** Run energy 0–100 (polled each game tick from client.getEnergy()). */
	@Getter @Setter private int runEnergy;

	/** Item ID of equipped ammo (-1 = none or not ranged). */
	@Getter @Setter private int ammoItemId = -1;

	/** Quantity of equipped ammo (0 when ammoItemId == -1). */
	@Getter @Setter private int ammoQuantity = 0;

	// ── Freeze helpers ────────────────────────────────────────────────────────

	public boolean isFrozen(int currentTick)
	{
		return freezeEndTick > currentTick;
	}

	public int getFreezeTicksRemaining(int currentTick)
	{
		if (freezeEndTick < 0) return 0;
		return Math.max(0, freezeEndTick - currentTick);
	}

	/**
	 * Applies a freeze starting at {@code startTick} for {@code durationTicks}.
	 * No-op if the player is already frozen — repeated impacts must not extend it.
	 */
	public void applyFreeze(int startTick, int durationTicks, int spriteId)
	{
		if (isFrozen(startTick)) return;
		freezeStartTick = startTick;
		freezeEndTick   = startTick + durationTicks;
		freezeSpriteId  = spriteId;
	}

	/**
	 * Natural freeze expiry — timer ran out. Grants post-thaw refreeze immunity.
	 * Call this when {@link #isFrozen} transitions to false via the tick counter.
	 */
	public void expireFreeze(int currentTick)
	{
		if (freezeEndTick > 0 && freezeStartTick >= 0)
			refreezeImmunityEndTick = currentTick + REFREEZE_IMMUNITY_TICKS;
		freezeStartTick = -1;
		freezeEndTick   = -1;
		freezeSpriteId  = 0;
	}

	/**
	 * Breaks the freeze early (movement detected, or tracked opponent died in single-combat).
	 * Does NOT grant refreeze immunity — only natural expiry awards it.
	 */
	public void breakFreezeEarly()
	{
		freezeStartTick = -1;
		freezeEndTick   = -1;
		freezeSpriteId  = 0;
	}

	/** Clears the freeze without granting immunity (logout, death, world-hop). */
	public void clearFreeze()
	{
		freezeStartTick         = -1;
		freezeEndTick           = -1;
		freezeSpriteId          = 0;
		refreezeImmunityEndTick = -1;
	}

	// ── Refreeze immunity ─────────────────────────────────────────────────────

	public boolean isRefreezeImmune(int currentTick)
	{
		return refreezeImmunityEndTick > currentTick;
	}

	public int getRefreezeImmunityTicks(int currentTick)
	{
		if (refreezeImmunityEndTick < 0) return 0;
		return Math.max(0, refreezeImmunityEndTick - currentTick);
	}

	// ── Prayer lock (Dragon scimitar Sever) ───────────────────────────────────

	/** Applies an 8-tick protection-prayer lock starting at {@code currentTick}. */
	public void applyPrayerLock(int currentTick)
	{
		prayerLockEndTick = currentTick + 8;
	}

	public boolean isPrayerLocked(int currentTick)
	{
		return prayerLockEndTick > currentTick;
	}

	public int getPrayerLockTicksRemaining(int currentTick)
	{
		if (prayerLockEndTick < 0) return 0;
		return Math.max(0, prayerLockEndTick - currentTick);
	}

	public void reset()
	{
		clearFreeze();
		tbImmunityActive        = false;
		prayerLockEndTick       = -1;
		teleBlockTicksRemaining = 0;
		currentHp               = 0;
		maxHp                   = 0;
		currentPrayer           = 0;
		maxPrayer               = 0;
		lastIncomingDamageMs    = -1;
		lastIncomingDamage      = 0;
		runEnergy               = 0;
		ammoItemId              = -1;
		ammoQuantity            = 0;
	}
}

package com.pvphud;

import com.pvphud.state.ActionClockState;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for the absolute-tick-deadline action clock model.
 *
 * All "remaining ticks" values are derived as (deadline - currentTick),
 * clamped to 0 for display.  The raw deadlines are never clamped — this
 * preserves idle-attack credit for food interactions.
 */
public class ActionClockTest
{
	private ActionClockState clock;

	@Before
	public void setUp()
	{
		clock = new ActionClockState();
	}

	// ── Attack delay ──────────────────────────────────────────────────────────

	@Test
	public void attack_beforeFirstHit_returnsZeroDelay()
	{
		assertFalse("has not attacked", clock.hasAttacked());
		assertEquals(0, clock.getAttackDelayTicks(100));
