package com.pvphud;

import com.pvphud.state.SelfState;
import net.runelite.api.SpriteID;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Validates the two distinct freeze-termination paths:
 *   A. expireFreeze — natural timer expiry → grants refreeze immunity
 *   B. breakFreezeEarly — movement / opponent-death → no immunity
 */
public class FreezeLifecycleTest
{
	// A — natural expiry

	@Test
	public void expireFreeze_clearsFreezeState()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.expireFreeze(32);
		assertFalse(s.isFrozen(32));
		assertEquals(0, s.getFreezeTicksRemaining(32));
		assertEquals(-1, s.getFreezeStartTick());
	}

	@Test
	public void expireFreeze_grantsRefreezeImmunity()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.expireFreeze(32);
		assertTrue("refreeze immunity must be granted after natural expiry", s.isRefreezeImmune(32));
		assertTrue(s.isRefreezeImmune(36));   // immunity still active
		assertFalse(s.isRefreezeImmune(37));  // immunity ended at 32 + 5 = 37
	}

	// B — early break (movement / opponent death)

	@Test
	public void breakFreezeEarly_clearsFreezeState()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.breakFreezeEarly();
		assertFalse(s.isFrozen(10));
		assertEquals(-1, s.getFreezeStartTick());
		assertEquals(0, s.getFreezeSpriteId());
	}

	@Test
	public void breakFreezeEarly_doesNotGrantImmunity()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.breakFreezeEarly();
		assertFalse("breakFreezeEarly must not grant refreeze immunity", s.isRefreezeImmune(1));
		assertFalse(s.isRefreezeImmune(10));
	}

	@Test
	public void breakFreezeEarly_whenNotFrozen_isNoop()
	{
		SelfState s = new SelfState();
		s.breakFreezeEarly(); // should not throw; should not affect immunity
		assertFalse(s.isRefreezeImmune(0));
		assertEquals(-1, s.getFreezeStartTick());
	}

	// C — clearFreeze (logout / death) — always existed, verify still works

	@Test
	public void clearFreeze_clearsStateAndImmunity()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.expireFreeze(32); // gain immunity
		assertTrue(s.isRefreezeImmune(32));
		s.clearFreeze();    // should wipe immunity too
		assertFalse(s.isRefreezeImmune(32));
		assertEquals(-1, s.getFreezeStartTick());
	}
}

package com.pvphud;

import com.pvphud.PvpHudState;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.EnumMap;
import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Verifies the gameframe-transition contracts:
 *
 *   - detectGameframe() correctly classifies Fixed, Resizable Classic, Resizable Modern.
 *   - Float positions are stored per-layout × per-gameframe; no cross-contamination.
 *   - Gameframe transitions mark layout geometry dirty but do NOT reset combat state.
 *   - Inventory Hug anchor is invalidated on gameframe change.
 *   - Horizontal Float reads live chatbox bounds, independent of the Chat Locked path.
 *   - Entering a float layout with no saved position does not inherit a locked anchor.
 *
 * All tests are deterministic and require no live RuneLite Client.
 */
public class GameframeTransitionTest
{
    // ── detectGameframe() ─────────────────────────────────────────────────────

    @Test
    public void detectGameframe_notResized_alwaysFixed()
    {
        // isResized=false must yield FIXED regardless of top-level interface ID
        assertEquals(GameframeType.FIXED,
            PvpHudOverlay.detectGameframe(false, InterfaceID.TOPLEVEL_OSRS_STRETCH));
        assertEquals(GameframeType.FIXED,
            PvpHudOverlay.detectGameframe(false, InterfaceID.TOPLEVEL_PRE_EOC));
        assertEquals(GameframeType.FIXED,
            PvpHudOverlay.detectGameframe(false, InterfaceID.TOPLEVEL));
    }

    @Test
    public void detectGameframe_resized_stretch_isResizableClassic()
    {
        assertEquals(GameframeType.RESIZABLE_CLASSIC,
            PvpHudOverlay.detectGameframe(true, InterfaceID.TOPLEVEL_OSRS_STRETCH));
    }

    @Test
    public void detectGameframe_resized_preEoc_isResizableModern()
    {
        assertEquals(GameframeType.RESIZABLE_MODERN,
            PvpHudOverlay.detectGameframe(true, InterfaceID.TOPLEVEL_PRE_EOC));
    }

    @Test
    public void detectGameframe_resized_unknownTopLevel_defaultsToClassic()
    {
        // An unknown top-level interface while resized defaults to RESIZABLE_CLASSIC
        assertEquals(GameframeType.RESIZABLE_CLASSIC,
            PvpHudOverlay.detectGameframe(true, InterfaceID.TOPLEVEL));
    }

    // ── Float position isolation across gameframes ────────────────────────────

    @Test
    public void fixedPosition_notInherited_byResizableModern()
    {
        // Saving a position for FIXED must not make it visible under RESIZABLE_MODERN
        EnumMap<GameframeType, Point> positions = new EnumMap<>(GameframeType.class);
        positions.put(GameframeType.FIXED, new Point(100, 200));

        assertNull("RESIZABLE_MODERN position is absent",
            positions.get(GameframeType.RESIZABLE_MODERN));
        assertNull("RESIZABLE_CLASSIC position is absent",
            positions.get(GameframeType.RESIZABLE_CLASSIC));
    }

    @Test
    public void fixedPosition_notInherited_byResizableClassic()
    {
        EnumMap<GameframeType, Point> positions = new EnumMap<>(GameframeType.class);
        positions.put(GameframeType.FIXED, new Point(50, 75));

        assertNull(positions.get(GameframeType.RESIZABLE_CLASSIC));
    }

    @Test
    public void savingResizableModernPosition_doesNotOverwriteFixed()
    {
        EnumMap<GameframeType, Point> positions = new EnumMap<>(GameframeType.class);
        Point fixedPt  = new Point(10, 20);
        Point modernPt = new Point(300, 400);
        positions.put(GameframeType.FIXED,            fixedPt);
        positions.put(GameframeType.RESIZABLE_MODERN, modernPt);

        assertEquals("FIXED position unchanged", fixedPt,  positions.get(GameframeType.FIXED));
        assertEquals("MODERN position correct",  modernPt, positions.get(GameframeType.RESIZABLE_MODERN));
    }

    @Test
    public void horizAndVertPositions_areStoredIndependently()
    {
        EnumMap<GameframeType, Point> horizPositions = new EnumMap<>(GameframeType.class);
        EnumMap<GameframeType, Point> vertPositions  = new EnumMap<>(GameframeType.class);

        Point hFixed = new Point(10, 20);
        Point vFixed = new Point(30, 40);
        horizPositions.put(GameframeType.FIXED, hFixed);
        vertPositions.put(GameframeType.FIXED,  vFixed);

        // Horiz-Fixed does not appear in vert map, and vice-versa
        assertEquals(hFixed, horizPositions.get(GameframeType.FIXED));
        assertEquals(vFixed, vertPositions.get(GameframeType.FIXED));
        assertNull("vert has no MODERN entry", vertPositions.get(GameframeType.RESIZABLE_MODERN));
        assertNull("horiz has no MODERN entry", horizPositions.get(GameframeType.RESIZABLE_MODERN));
    }

    @Test
    public void firstTimeFloat_noSavedPosition_returnsNull()
    {
        // When entering a float layout for the first time in a gameframe,
        // positions.get(gameframe) == null → setPreferredLocation(null).
        // This clears any locked-layout anchor so the float starts without inheriting it.
        EnumMap<GameframeType, Point> positions = new EnumMap<>(GameframeType.class);
        assertNull("no position saved yet for FIXED", positions.get(GameframeType.FIXED));
        assertNull("no position saved yet for CLASSIC", positions.get(GameframeType.RESIZABLE_CLASSIC));
        assertNull("no position saved yet for MODERN",  positions.get(GameframeType.RESIZABLE_MODERN));
    }

    // ── Combat state not reset on gameframe change ────────────────────────────

    @Test
    public void gameframeChange_preservesCombatState()
    {
        // Gameframe change must only touch layout geometry, never fullReset().
        PvpHudState state = new PvpHudState();
        state.beginSession("Target", 1000);
        state.getSelf().setCurrentHp(77);
        state.getContext().setInPvpZone(true);
        state.getEffects().setSpecEnergy(80);

        // What onGameframeChanged() does:
        state.getLayout().markDirty();
        // inventoryHugAnchorDirty = true (overlay internal, not accessible here)

        assertNotNull("session preserved", state.getCurrentSession());
        assertEquals("HP preserved", 77, state.getSelf().getCurrentHp());
        assertTrue("pvp zone preserved", state.getContext().isInPvpZone());
        assertEquals("spec preserved", 80, state.getEffects().getSpecEnergy());
    }

    @Test
    public void allTransitions_preserveCombatState()
    {
        GameframeType[][] transitions = {
            {GameframeType.FIXED, GameframeType.RESIZABLE_CLASSIC},
            {GameframeType.FIXED, GameframeType.RESIZABLE_MODERN},
            {GameframeType.RESIZABLE_CLASSIC, GameframeType.RESIZABLE_MODERN},
            {GameframeType.RESIZABLE_MODERN, GameframeType.RESIZABLE_CLASSIC},
            {GameframeType.RESIZABLE_CLASSIC, GameframeType.FIXED},
            {GameframeType.RESIZABLE_MODERN, GameframeType.FIXED},
        };
        for (GameframeType[] t : transitions)
        {
            PvpHudState state = new PvpHudState();
            state.beginSession("P", 0);
            state.getSelf().setCurrentHp(99);

            state.getLayout().markDirty(); // simulate gameframe transition

            assertNotNull("session preserved: " + t[0] + " -> " + t[1], state.getCurrentSession());
            assertEquals("HP preserved: " + t[0] + " -> " + t[1], 99, state.getSelf().getCurrentHp());
        }
    }

    // ── Layout dirty on gameframe change ─────────────────────────────────────

    @Test
    public void gameframeChange_marksLayoutDirty()
    {
        PvpHudState state = new PvpHudState();
        state.getLayout().setDirty(false);

        state.getLayout().markDirty(); // what onGameframeChanged() does

        assertTrue(state.getLayout().isDirty());
    }

    @Test
    public void allTransitions_allLayouts_markLayoutDirty()
    {
        GameframeType[][] transitions = {
            {GameframeType.FIXED, GameframeType.RESIZABLE_CLASSIC},
            {GameframeType.FIXED, GameframeType.RESIZABLE_MODERN},
            {GameframeType.RESIZABLE_CLASSIC, GameframeType.RESIZABLE_MODERN},
            {GameframeType.RESIZABLE_MODERN, GameframeType.RESIZABLE_CLASSIC},
            {GameframeType.RESIZABLE_CLASSIC, GameframeType.FIXED},
        };
        for (GameframeType[] t : transitions)
        {
            for (HudLayout layout : HudLayout.values())
            {
                PvpHudState state = new PvpHudState();
                state.getLayout().setDirty(false);

                state.getLayout().markDirty();

                assertTrue("layout dirty: " + layout + " " + t[0] + " -> " + t[1],
                    state.getLayout().isDirty());
            }
        }
    }

    // ── HorizFloat chatbox dimension independence ─────────────────────────────

    @Test
    public void horizFloat_staleChatboxBounds_replacedByFreshBounds()
    {
        // Simulate: Chat Locked in Fixed frame stored 519x165 in layout.
        // Gameframe switches to Resizable → layout marked dirty.
        // renderHorizontalFloat reads live chatbox → 754x168 → updates layout.
        PvpHudState state = new PvpHudState();
        state.getLayout().setChatboxBounds(new Rectangle(0, 0, 519, 165));
        state.getLayout().setDirty(false);

        // Gameframe change
        state.getLayout().markDirty();
        assertTrue("dirty after gameframe change", state.getLayout().isDirty());

        // Simulate renderHorizontalFloat reading live chatbox (getChatboxBounds())
        Rectangle liveBounds = new Rectangle(0, 0, 754, 168);
        if (!liveBounds.equals(state.getLayout().getChatboxBounds()))
        {
            state.getLayout().setChatboxBounds(new Rectangle(liveBounds));
            // computeHorizLayout would fire here (layout still dirty)
        }
        assertEquals("fresh width applied", 754, state.getLayout().getChatboxBounds().width);
        assertEquals("fresh height applied", 168, state.getLayout().getChatboxBounds().height);
    }

    @Test
    public void horizFloat_noChatLockedVisit_freshBoundsUsed()
    {
        // Contract: HorizFloat must NOT gate on layout.getChatboxBounds() being populated.
        // It reads getChatboxBounds() live each frame.
        // Proof by structure: if chatboxBounds is null (never visited Chat Locked),
        // renderHorizontalFloat falls back to (519, 200) and does NOT return null.
        PvpHudState state = new PvpHudState();
        assertNull("chatboxBounds not populated yet", state.getLayout().getChatboxBounds());

        // renderHorizontalFloat with null chatboxBounds would use fallback 519x200
        // (equivalent: currentChat == null → w=519, h=200 in the implementation)
        int expectedW = 519;
        int expectedH = 200;
        // Verify fallback values are positive (overlay can render)
        assertTrue(expectedW > 0);
        assertTrue(expectedH > 0);
    }

    // ── Vertical Float dimensions unchanged across gameframes ─────────────────

    @Test
    public void verticalFloat_dimensionsAreGameframeIndependent()
    {
        // VERT_W=220, VERT_H=400 are hardcoded constants in renderVerticalFloat.
        // The method never calls getChatboxBounds().
        // This is verified by code structure — no test double needed.
        // We exercise the three-value enum to ensure all gameframes compile and exist.
        for (GameframeType gf : GameframeType.values())
        {
            // Switching gameframe in vert-float only affects position, never dimensions.
            assertNotNull("gameframe constant exists: " + gf, gf);
        }
    }

    // ── Enum completeness ─────────────────────────────────────────────────────

    @Test
    public void gameframeType_hasExactlyThreeValues()
    {
        assertEquals(3, GameframeType.values().length);
    }

    @Test
    public void gameframeType_allValuesDistinct()
    {
        assertNotEquals(GameframeType.FIXED, GameframeType.RESIZABLE_CLASSIC);
        assertNotEquals(GameframeType.FIXED, GameframeType.RESIZABLE_MODERN);
        assertNotEquals(GameframeType.RESIZABLE_CLASSIC, GameframeType.RESIZABLE_MODERN);
    }
}

package com.pvphud;

import com.pvphud.state.OpponentState;
import com.pvphud.state.OpponentStats;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Exercises the account-type polling helpers and the opponent-name guard used
 * by the hiscore polling loop in {@link PvpHudPlugin}.
 *
 * <p>{@code HiscoreManager.lookupAsync} returns null both for "still loading"
 * and for "player not on this endpoint" — there is no way to distinguish the
 * two via the public API. Rather than try to track resolved-negative state,
 * the production loop records the best-observed positive account type across
 * polls and commits at a bounded deadline. {@link HiscoreAccountResolver}
 * provides {@code best()} (precedence upgrade) and {@code isTerminal()}
 * (HC can short-circuit the loop) to drive that process.
 */
public class HiscoreLifecycleTest
{
	// ── best(): precedence upgrades ───────────────────────────────────────────

	@Test
	public void best_normalToIronman_upgrades()
	{
		assertEquals(OpponentStats.AccountType.IRONMAN,
			HiscoreAccountResolver.best(
				OpponentStats.AccountType.NORMAL,
				OpponentStats.AccountType.IRONMAN));
	}

	@Test
	public void best_ironmanToUim_upgrades()
	{
		assertEquals(OpponentStats.AccountType.ULTIMATE_IRONMAN,
			HiscoreAccountResolver.best(
				OpponentStats.AccountType.IRONMAN,
				OpponentStats.AccountType.ULTIMATE_IRONMAN));
	}

	@Test
	public void best_uimToHc_upgrades()
	{
		assertEquals(OpponentStats.AccountType.HARDCORE_IRONMAN,
			HiscoreAccountResolver.best(
				OpponentStats.AccountType.ULTIMATE_IRONMAN,
				OpponentStats.AccountType.HARDCORE_IRONMAN));
	}

	// ── best(): no downgrade ──────────────────────────────────────────────────

	@Test
	public void best_hcToIronman_stays()
	{
		assertEquals("HC must not downgrade",
			OpponentStats.AccountType.HARDCORE_IRONMAN,
			HiscoreAccountResolver.best(
				OpponentStats.AccountType.HARDCORE_IRONMAN,
				OpponentStats.AccountType.IRONMAN));
	}

	@Test
	public void best_ironmanToNormal_stays()
	{
		assertEquals("IM must not downgrade to NORMAL",
			OpponentStats.AccountType.IRONMAN,
			HiscoreAccountResolver.best(
				OpponentStats.AccountType.IRONMAN,
				OpponentStats.AccountType.NORMAL));
	}

	@Test
	public void best_normalToNormal_stays()
	{
		assertEquals(OpponentStats.AccountType.NORMAL,
			HiscoreAccountResolver.best(
				OpponentStats.AccountType.NORMAL,
				OpponentStats.AccountType.NORMAL));
	}

	// ── isTerminal() ──────────────────────────────────────────────────────────

	@Test
	public void isTerminal_hc_true()
	{
		assertTrue(HiscoreAccountResolver.isTerminal(OpponentStats.AccountType.HARDCORE_IRONMAN));
	}

	@Test
	public void isTerminal_uim_false()
	{
		assertFalse(HiscoreAccountResolver.isTerminal(OpponentStats.AccountType.ULTIMATE_IRONMAN));
	}

	@Test
	public void isTerminal_im_false()
	{
		assertFalse(HiscoreAccountResolver.isTerminal(OpponentStats.AccountType.IRONMAN));
	}

	@Test
	public void isTerminal_normal_false()
	{
		assertFalse(HiscoreAccountResolver.isTerminal(OpponentStats.AccountType.NORMAL));
	}

	// ── Lifecycle simulations ─────────────────────────────────────────────────
	//
	// The following tests simulate the real polling loop semantics. Each
	// "poll" interprets a per-endpoint response of null (loading or absent)
	// vs HP>0 (positive hit) and applies the production logic: HC positive
	// terminates immediately; UIM/IM positive upgrade `best`; at the deadline
	// the final `best` is applied.

	/** Null-safe stand-in for an endpoint check that returns positive or absent. */
	private static OpponentStats.AccountType pollEndpoint(
		OpponentStats.AccountType current,
		OpponentStats.AccountType candidateIfPositive,
		boolean positive)
	{
		return positive ? HiscoreAccountResolver.best(current, candidateIfPositive) : current;
	}

	@Test
	public void lifecycle_poll1_hcNull_uimNull_imPositive_pending()
	{
		OpponentStats.AccountType best = OpponentStats.AccountType.NORMAL;
		best = pollEndpoint(best, OpponentStats.AccountType.HARDCORE_IRONMAN, false);
		best = pollEndpoint(best, OpponentStats.AccountType.ULTIMATE_IRONMAN, false);
		best = pollEndpoint(best, OpponentStats.AccountType.IRONMAN, true);
		assertEquals(OpponentStats.AccountType.IRONMAN, best);
		assertFalse("IM alone is not terminal — HC may still resolve",
			HiscoreAccountResolver.isTerminal(best));
	}

	@Test
	public void lifecycle_poll2_hcPositive_terminalCompletesAsHc()
	{
		OpponentStats.AccountType best = OpponentStats.AccountType.IRONMAN; // from poll 1
		best = pollEndpoint(best, OpponentStats.AccountType.HARDCORE_IRONMAN, true);
		assertEquals(OpponentStats.AccountType.HARDCORE_IRONMAN, best);
		assertTrue(HiscoreAccountResolver.isTerminal(best));
	}

	@Test
	public void lifecycle_fullWindow_hcUimAlwaysNull_imPositive_bestIsIm()
	{
		OpponentStats.AccountType best = OpponentStats.AccountType.NORMAL;
		for (int poll = 0; poll < 10; poll++)
		{
			best = pollEndpoint(best, OpponentStats.AccountType.HARDCORE_IRONMAN, false);
			best = pollEndpoint(best, OpponentStats.AccountType.ULTIMATE_IRONMAN, false);
			best = pollEndpoint(best, OpponentStats.AccountType.IRONMAN, true);
		}
		assertEquals(OpponentStats.AccountType.IRONMAN, best);
	}

	@Test
	public void lifecycle_fullWindow_allNull_bestStaysNormal()
	{
		OpponentStats.AccountType best = OpponentStats.AccountType.NORMAL;
		for (int poll = 0; poll < 10; poll++)
		{
			best = pollEndpoint(best, OpponentStats.AccountType.HARDCORE_IRONMAN, false);
			best = pollEndpoint(best, OpponentStats.AccountType.ULTIMATE_IRONMAN, false);
			best = pollEndpoint(best, OpponentStats.AccountType.IRONMAN, false);
		}
		assertEquals(OpponentStats.AccountType.NORMAL, best);
	}

	@Test
	public void lifecycle_uimPositive_hcAlwaysNull_bestIsUim()
	{
		OpponentStats.AccountType best = OpponentStats.AccountType.NORMAL;
		for (int poll = 0; poll < 10; poll++)
		{
			best = pollEndpoint(best, OpponentStats.AccountType.HARDCORE_IRONMAN, false);
			best = pollEndpoint(best, OpponentStats.AccountType.ULTIMATE_IRONMAN, true);
			best = pollEndpoint(best, OpponentStats.AccountType.IRONMAN, false);
			assertFalse("UIM is not terminal while HC could still resolve",
				HiscoreAccountResolver.isTerminal(best));
		}
		assertEquals(OpponentStats.AccountType.ULTIMATE_IRONMAN, best);
	}

	@Test
	public void lifecycle_hcPositiveImmediately_terminalBeforeDeadline()
	{
		// Poll 1: HC comes back positive straight away. Loop can terminate.
		OpponentStats.AccountType best = OpponentStats.AccountType.NORMAL;
		best = pollEndpoint(best, OpponentStats.AccountType.HARDCORE_IRONMAN, true);
		assertEquals(OpponentStats.AccountType.HARDCORE_IRONMAN, best);
		assertTrue("HC on poll 1 must be terminal — no need to wait",
			HiscoreAccountResolver.isTerminal(best));
	}

	// ── Opponent-change guard ────────────────────────────────────────────────

	@Test
	public void opponentChange_invalidatesOldResult()
	{
		OpponentState opp = new OpponentState();
		opp.setName("Bob");
		String pendingPlayer = "Alice";
		boolean wouldApply = pendingPlayer.equalsIgnoreCase(opp.getName());
		assertFalse("Result for Alice must not apply when opponent is Bob", wouldApply);
	}

	@Test
	public void result_appliesWhenOpponentMatches()
	{
		OpponentState opp = new OpponentState();
		opp.setName("Alice");
		boolean nameMatches = "Alice".equalsIgnoreCase(opp.getName());
		assertTrue(nameMatches);
	}

	// ── Deadline fires even when NORMAL stats never load ─────────────────────
	//
	// Prior bug: deadline was gated on `normalDone && elapsed >= timeout`.
	// If NORMAL endpoint always returns null (player not on hiscores, slow
	// network, etc.) `normalDone` was never true, so polling ran indefinitely.
	// The fix removes the `normalDone` guard so the deadline fires unconditionally.

	@Test
	public void deadline_imPositive_normalNeverLoads_bestIsIm()
	{
		// Simulate: NORMAL always null, IM positive on every poll, deadline reached.
		OpponentStats.AccountType best = OpponentStats.AccountType.NORMAL;
		boolean normalDone = false;
		int elapsed = 0;
		final int timeout = 30; // HISCORE_TIMEOUT_TICKS

		while (elapsed < timeout)
		{
			// NORMAL returns null — normalDone stays false
			// HC returns null
			// IM returns positive
			best = pollEndpoint(best, OpponentStats.AccountType.IRONMAN, true);
			elapsed++;
		}

		// Deadline fires unconditionally (no normalDone guard).
		assertTrue("deadline must fire at elapsed>=timeout regardless of normalDone",
			elapsed >= timeout);
		assertEquals("best observed type must be committed at deadline",
			OpponentStats.AccountType.IRONMAN, best);
		assertFalse("normalDone must still be false to prove the guard was not in play", normalDone);
	}

	@Test
	public void deadline_allNull_normalNeverLoads_bestStaysNormal()
	{
		OpponentStats.AccountType best = OpponentStats.AccountType.NORMAL;
		int elapsed = 0;
		final int timeout = 30;

		while (elapsed < timeout)
		{
			// All endpoints null — no upgrade
			elapsed++;
		}

		assertTrue("deadline must fire", elapsed >= timeout);
		assertEquals("no positive hit → best remains NORMAL",
			OpponentStats.AccountType.NORMAL, best);
	}

	// ── Original ordinal-order guard retained ────────────────────────────────

	@Test
	public void accountType_ordinalPreventsDowngrade()
	{
		OpponentStats stats = new OpponentStats();
		stats.setAccountType(OpponentStats.AccountType.HARDCORE_IRONMAN);
		OpponentStats.AccountType incoming = OpponentStats.AccountType.IRONMAN;
		boolean wouldUpgrade = incoming.ordinal() > stats.getAccountType().ordinal();
		assertFalse("IM must not downgrade from HC", wouldUpgrade);
	}

	@Test
	public void accountType_ordinal_normalLowest()
	{
		assertEquals(0, OpponentStats.AccountType.NORMAL.ordinal());
		assertTrue(OpponentStats.AccountType.IRONMAN.ordinal()
			> OpponentStats.AccountType.NORMAL.ordinal());
		assertTrue(OpponentStats.AccountType.ULTIMATE_IRONMAN.ordinal()
			> OpponentStats.AccountType.IRONMAN.ordinal());
		assertTrue(OpponentStats.AccountType.HARDCORE_IRONMAN.ordinal()
			> OpponentStats.AccountType.ULTIMATE_IRONMAN.ordinal());
	}
}

package com.pvphud;

import com.pvphud.state.HudLayoutState;
import java.awt.Rectangle;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Verifies layout geometry for HORIZONTAL and VERTICAL HUD layouts.
 *
 * computeHorizLayout / computeVertLayout are package-private statics, callable
 * without a RuneLite client.  Tests cover:
 *   - every panel fits inside the outer bounds
 *   - no two panels overlap
 *   - action strip is the very last row (bottom of bounds)
 *   - total height exactly equals the outer bounds height
 *   - no panel has negative width or height
 */
public class HudLayoutBoundsTest
{
	// ── Helpers ───────────────────────────────────────────────────────────────

	private static void assertWithin(Rectangle panel, Rectangle bounds, String name)
	{
		assertTrue(name + ".x >= bounds.x",
			panel.x >= bounds.x);
		assertTrue(name + ".y >= bounds.y",
			panel.y >= bounds.y);
		assertTrue(name + ".right <= bounds.right",
			panel.x + panel.width  <= bounds.x + bounds.width);
		assertTrue(name + ".bottom <= bounds.bottom",
			panel.y + panel.height <= bounds.y + bounds.height);
	}

	private static void assertNoVertOverlap(Rectangle upper, Rectangle lower, String msg)
	{
		assertTrue(msg + ": upper.bottom=" + (upper.y + upper.height) + " must be <= lower.top=" + lower.y,
			upper.y + upper.height <= lower.y);
	}

	private static void assertNoHorizOverlap(Rectangle left, Rectangle right, String msg)
	{
		assertTrue(msg + ": left.right=" + (left.x + left.width) + " must be <= right.left=" + right.x,
			left.x + left.width <= right.x);
	}

	private static void assertNonNegativeSize(Rectangle r, String name)
	{
		if (r == null) return;
		assertTrue(name + ".width >= 0", r.width  >= 0);
		assertTrue(name + ".height >= 0", r.height >= 0);
	}

	// ── HORIZONTAL layout — chatbox-sized (519 × 143) ─────────────────────────

	@Test
	public void horiz_allPanelsFitWithinBounds()
	{
		HudLayoutState layout = new HudLayoutState();
		Rectangle b = new Rectangle(0, 0, 519, 143);
		PvpHudOverlay.computeHorizLayout(layout, b);

		assertWithin(layout.getOpponentPanel(), b, "opponent");
		assertWithin(layout.getEventPanel(),    b, "event");
		assertWithin(layout.getSelfPanel(),     b, "self");
		assertWithin(layout.getActionStrip(),   b, "actionStrip");
	}

	@Test
	public void horiz_mainPanelsDoNotOverlapHorizontally()
	{
		HudLayoutState layout = new HudLayoutState();
		Rectangle b = new Rectangle(0, 0, 519, 143);
		PvpHudOverlay.computeHorizLayout(layout, b);

		assertNoHorizOverlap(layout.getOpponentPanel(), layout.getEventPanel(), "opponent/event");
		assertNoHorizOverlap(layout.getEventPanel(),    layout.getSelfPanel(),  "event/self");
	}

	@Test
	public void horiz_verticalStackingNoOverlap()
	{
		HudLayoutState layout = new HudLayoutState();
		Rectangle b = new Rectangle(0, 0, 519, 143);
		PvpHudOverlay.computeHorizLayout(layout, b);

		// Action strip sits below main panels (no boost row anymore)
		assertNoVertOverlap(layout.getOpponentPanel(), layout.getActionStrip(), "opponent/strip");
	}

	@Test
	public void horiz_stripBottomEqualsOuterBoundsBottom()
	{
		HudLayoutState layout = new HudLayoutState();
		Rectangle b = new Rectangle(0, 0, 519, 143);
		PvpHudOverlay.computeHorizLayout(layout, b);

		Rectangle strip = layout.getActionStrip();
		assertEquals("strip fills to bounds bottom",
			b.y + b.height, strip.y + strip.height);
	}

	@Test
	public void horiz_mainPanelHeightsAreEqual()
	{
		HudLayoutState layout = new HudLayoutState();
		Rectangle b = new Rectangle(0, 0, 519, 143);
		PvpHudOverlay.computeHorizLayout(layout, b);

		assertEquals("opp.height == event.height",
			layout.getOpponentPanel().height, layout.getEventPanel().height);
		assertEquals("opp.height == self.height",
			layout.getOpponentPanel().height, layout.getSelfPanel().height);
	}

	@Test
	public void horiz_smallBounds_noNegativeSizes()
	{
		HudLayoutState layout = new HudLayoutState();
		Rectangle b = new Rectangle(0, 0, 90, 60);
		PvpHudOverlay.computeHorizLayout(layout, b);

		assertNonNegativeSize(layout.getOpponentPanel(), "opponent");
		assertNonNegativeSize(layout.getEventPanel(),    "event");
		assertNonNegativeSize(layout.getSelfPanel(),     "self");
		assertNonNegativeSize(layout.getActionStrip(),   "actionStrip");
	}

	@Test
	public void horiz_nonZeroOrigin_allCoordinatesOffsetCorrectly()
	{
		HudLayoutState at0   = new HudLayoutState();
		HudLayoutState at100 = new HudLayoutState();
		Rectangle b0   = new Rectangle(0,   0,   519, 143);
		Rectangle b100 = new Rectangle(100, 200, 519, 143);
		PvpHudOverlay.computeHorizLayout(at0,   b0);
		PvpHudOverlay.computeHorizLayout(at100, b100);

		assertEquals("opponent x offset",
			at0.getOpponentPanel().x + 100, at100.getOpponentPanel().x);
		assertEquals("strip y offset",
			at0.getActionStrip().y + 200, at100.getActionStrip().y);
	}

	// ── VERTICAL layout — 220 × 400 ───────────────────────────────────────────

	@Test
	public void vert_allPanelsFitWithinBounds()
	{
		HudLayoutState layout = new HudLayoutState();
		Rectangle b = new Rectangle(0, 0, 220, 400);
		PvpHudOverlay.computeVertLayout(layout, b);

		assertWithin(layout.getOpponentPanel(), b, "opponent");
		assertWithin(layout.getEventPanel(),    b, "event");
		assertWithin(layout.getSelfPanel(),     b, "self");
		assertWithin(layout.getActionStrip(),   b, "actionStrip");
	}

	@Test
	public void vert_verticalStackingNoOverlap()
	{
		HudLayoutState layout = new HudLayoutState();
		Rectangle b = new Rectangle(0, 0, 220, 400);
		PvpHudOverlay.computeVertLayout(layout, b);

		assertNoVertOverlap(layout.getOpponentPanel(), layout.getEventPanel(),  "opponent/event");
		assertNoVertOverlap(layout.getEventPanel(),    layout.getSelfPanel(),   "event/self");
		assertNoVertOverlap(layout.getSelfPanel(),     layout.getActionStrip(), "self/strip");
	}

	@Test
	public void vert_stripBottomEqualsOuterBoundsBottom()
	{
		HudLayoutState layout = new HudLayoutState();
		Rectangle b = new Rectangle(0, 0, 220, 400);
		PvpHudOverlay.computeVertLayout(layout, b);

		Rectangle strip = layout.getActionStrip();
		assertEquals("strip fills to bounds bottom",
			b.y + b.height, strip.y + strip.height);
	}

	@Test
	public void vert_selfPanelLargerThanOppOrEvent_reducedSections()
	{
		HudLayoutState layout = new HudLayoutState();
		Rectangle b = new Rectangle(0, 0, 220, 400);
		PvpHudOverlay.computeVertLayout(layout, b);

		assertTrue("self panel taller than opponent (33% reduction applied)",
			layout.getSelfPanel().height > layout.getOpponentPanel().height);
		assertTrue("self panel taller than event (33% reduction applied)",
			layout.getSelfPanel().height > layout.getEventPanel().height);
	}

	@Test
	public void vert_smallBounds_noNegativeSizes()
	{
		HudLayoutState layout = new HudLayoutState();
		Rectangle b = new Rectangle(0, 0, 90, 60);
		PvpHudOverlay.computeVertLayout(layout, b);

		assertNonNegativeSize(layout.getOpponentPanel(), "opponent");
		assertNonNegativeSize(layout.getEventPanel(),    "event");
		assertNonNegativeSize(layout.getSelfPanel(),     "self");
		assertNonNegativeSize(layout.getActionStrip(),   "actionStrip");
	}

	// ── allPanelsFullWidth invariant ─────────────────────────────────────────

	@Test
	public void vert_allPanelsSpanFullWidth()
	{
		HudLayoutState layout = new HudLayoutState();
		Rectangle b = new Rectangle(0, 0, 220, 400);
		PvpHudOverlay.computeVertLayout(layout, b);

		assertEquals("opponent spans full width", b.width, layout.getOpponentPanel().width);
		assertEquals("event spans full width",    b.width, layout.getEventPanel().width);
		assertEquals("self spans full width",     b.width, layout.getSelfPanel().width);
		assertEquals("strip spans full width",    b.width, layout.getActionStrip().width);
	}
}

package com.pvphud;

import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for the single HUD visibility predicate: PvpHudPlugin.computeShouldShow().
 *
 * Truth table:
 *   enabled=false              → false always
 *   enabled=true, MANUAL       → true always
 *   enabled=true, PVP_AREA     → true iff inPvpZone
 *   enabled=true, AUTO         → true iff hasSession
 */
public class HudVisibilityTest
{
	// ── Disabled flag gates all modes ─────────────────────────────────────────

	@Test
	public void disabled_manual_hides()
	{
		assertFalse(PvpHudPlugin.computeShouldShow(false, HudMode.MANUAL, false, false));
	}

	@Test
	public void disabled_pvpArea_inZone_hides()
	{
		assertFalse(PvpHudPlugin.computeShouldShow(false, HudMode.PVP_AREA, true, false));
	}

	@Test
	public void disabled_auto_hasSession_hides()
	{
		assertFalse(PvpHudPlugin.computeShouldShow(false, HudMode.AUTO, false, true));
	}

	// ── MANUAL mode ───────────────────────────────────────────────────────────

	@Test
	public void manual_enabled_noZone_noSession_shows()
	{
		assertTrue(PvpHudPlugin.computeShouldShow(true, HudMode.MANUAL, false, false));
	}

	@Test
	public void manual_enabled_inZone_shows()
	{
		assertTrue(PvpHudPlugin.computeShouldShow(true, HudMode.MANUAL, true, false));
	}

	@Test
	public void manual_enabled_hasSession_shows()
	{
		assertTrue(PvpHudPlugin.computeShouldShow(true, HudMode.MANUAL, false, true));
	}

	// ── PVP_AREA mode ─────────────────────────────────────────────────────────

	@Test
	public void pvpArea_enabled_inZone_shows()
	{
		assertTrue(PvpHudPlugin.computeShouldShow(true, HudMode.PVP_AREA, true, false));
	}

	@Test
	public void pvpArea_enabled_notInZone_hides()
	{
		assertFalse(PvpHudPlugin.computeShouldShow(true, HudMode.PVP_AREA, false, false));
	}

	@Test
	public void pvpArea_enabled_inZone_sessionIrrelevant_shows()
	{
		// hasSession does not affect PVP_AREA
		assertTrue(PvpHudPlugin.computeShouldShow(true, HudMode.PVP_AREA, true, true));
	}

	@Test
	public void pvpArea_enabled_notInZone_sessionCannotOverride_hides()
	{
		assertFalse(PvpHudPlugin.computeShouldShow(true, HudMode.PVP_AREA, false, true));
	}

	// ── AUTO mode ─────────────────────────────────────────────────────────────

	@Test
	public void auto_enabled_hasSession_shows()
	{
		assertTrue(PvpHudPlugin.computeShouldShow(true, HudMode.AUTO, false, true));
	}

	@Test
	public void auto_enabled_noSession_hides()
	{
		assertFalse(PvpHudPlugin.computeShouldShow(true, HudMode.AUTO, false, false));
	}

	@Test
	public void auto_enabled_inZone_noSession_hides()
	{
		// zone alone does not trigger AUTO
		assertFalse(PvpHudPlugin.computeShouldShow(true, HudMode.AUTO, true, false));
	}

	@Test
	public void auto_enabled_inZone_hasSession_shows()
	{
		assertTrue(PvpHudPlugin.computeShouldShow(true, HudMode.AUTO, true, true));
	}

	// ── Mode switching re-evaluates immediately ───────────────────────────────

	@Test
	public void modeSwitchAutoToManual_showsWithoutSession()
	{
		assertFalse(PvpHudPlugin.computeShouldShow(true, HudMode.AUTO,   false, false));
		assertTrue( PvpHudPlugin.computeShouldShow(true, HudMode.MANUAL, false, false));
