package com.pvphud;

import com.pvphud.PvpHudPlugin;
import com.pvphud.state.SelfState;
import net.runelite.api.GraphicID;
import net.runelite.api.SpriteID;
import net.runelite.api.gameval.SpotanimID;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Verifies that the freeze timer:
 *  - starts only from the confirmed "frozen" event (chat message),
 *  - is stored as startTick/endTick so remaining time is derived from the
 *    current tick rather than blindly decremented,
 *  - is NOT extended or reset by repeated ice impacts while already frozen,
 *  - uses RuneLite-matching base durations for all freeze spell types, and
 *  - is cleared by reset() / clearFreeze().
 */
public class SelfFreezeTimerTest
{
	// ── Base durations (must match PvpHudPlugin.freezeTicksForGraphic) ──────────

	@Test
	public void iceRush_baseDuration()
	{
		assertEquals(8, PvpHudPlugin.freezeTicksForGraphic(GraphicID.ICE_RUSH));
	}

	@Test
	public void iceBurst_baseDuration()
	{
		assertEquals(16, PvpHudPlugin.freezeTicksForGraphic(GraphicID.ICE_BURST));
	}

	@Test
	public void iceBlitz_baseDuration()
	{
		assertEquals(24, PvpHudPlugin.freezeTicksForGraphic(GraphicID.ICE_BLITZ));
	}

	@Test
	public void iceBarrage_baseDuration()
	{
		assertEquals(32, PvpHudPlugin.freezeTicksForGraphic(GraphicID.ICE_BARRAGE));
	}

	@Test
	public void bind_baseDuration()
	{
		assertEquals(8, PvpHudPlugin.freezeTicksForGraphic(SpotanimID.BIND_IMPACT));
	}

	@Test
	public void snare_baseDuration()
	{
		assertEquals(16, PvpHudPlugin.freezeTicksForGraphic(SpotanimID.SNARE_IMPACT));
	}

	@Test
	public void entangle_baseDuration()
	{
		assertEquals(24, PvpHudPlugin.freezeTicksForGraphic(SpotanimID.ENTANGLE_IMPACT));
	}

	@Test
	public void unknownGraphic_returnsZero()
	{
		assertEquals(0, PvpHudPlugin.freezeTicksForGraphic(999));
		assertEquals(0, PvpHudPlugin.freezeTicksForGraphic(0));
		assertEquals(0, PvpHudPlugin.freezeTicksForGraphic(-1));
	}

	// ── applyFreeze — startTick/endTick semantics ─────────────────────────────

	@Test
	public void applyFreeze_setsTimerCorrectly()
	{
		SelfState s = new SelfState();
		s.applyFreeze(10, 32, SpriteID.SPELL_ICE_BARRAGE);
		assertEquals(32, s.getFreezeTicksRemaining(10));
		assertEquals(1,  s.getFreezeTicksRemaining(41));
		assertEquals(0,  s.getFreezeTicksRemaining(42)); // exactly expired
	}

	@Test
	public void applyFreeze_remainingDerivesFromCurrentTick()
	{
		// Derived — not a counter: asking at different ticks gives correct answers
		// without needing any tick() / decrement calls.
		SelfState s = new SelfState();
		s.applyFreeze(0, 24, SpriteID.SPELL_ICE_BLITZ);
		assertEquals(24, s.getFreezeTicksRemaining(0));
		assertEquals(20, s.getFreezeTicksRemaining(4));
		assertEquals(12, s.getFreezeTicksRemaining(12));
		assertEquals(1,  s.getFreezeTicksRemaining(23));
		assertEquals(0,  s.getFreezeTicksRemaining(24));
	}

	@Test
	public void applyFreeze_pastEndTick_returnsZero()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 8, SpriteID.SPELL_ICE_RUSH);
		assertEquals(0, s.getFreezeTicksRemaining(100)); // well past expiry
	}

	// ── Repeated ice impacts while frozen must NOT extend the timer ──────────

	@Test
	public void repeatedImpact_doesNotExtendTimer()
	{
		SelfState s = new SelfState();
		s.applyFreeze(10, 32, SpriteID.SPELL_ICE_BARRAGE); // barrage at tick 10, ends at 42
		s.applyFreeze(15, 32, SpriteID.SPELL_ICE_BARRAGE); // second barrage at tick 15 — ignored
		// Timer must still end at tick 42, not 47
		assertEquals(27, s.getFreezeTicksRemaining(15));
		assertEquals(0,  s.getFreezeTicksRemaining(42));
	}

	@Test
	public void repeatedImpact_differentSpell_doesNotResetDuration()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE); // barrage at tick 0
		s.applyFreeze(5, 8, SpriteID.SPELL_ICE_RUSH);     // rush at tick 5 — ignored while frozen
		assertEquals(27, s.getFreezeTicksRemaining(5));    // 32 - 5 = 27, not 8
	}

	@Test
	public void newFreezeApplied_afterPreviousExpires()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 8, SpriteID.SPELL_ICE_RUSH);   // expires at tick 8
		s.applyFreeze(8, 32, SpriteID.SPELL_ICE_BARRAGE); // tick 8 = new freeze allowed
		assertEquals(32, s.getFreezeTicksRemaining(8));
	}

	// ── isFrozen ─────────────────────────────────────────────────────────────

	@Test
	public void isFrozen_trueWhileActive()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 16, SpriteID.SPELL_ICE_BURST);
		assertTrue(s.isFrozen(0));
		assertTrue(s.isFrozen(15));
	}

	@Test
	public void isFrozen_falseAtExpiry()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 16, SpriteID.SPELL_ICE_BURST);
		assertFalse(s.isFrozen(16));
		assertFalse(s.isFrozen(100));
	}

	@Test
	public void isFrozen_falseWhenNoFreezeApplied()
	{
		SelfState s = new SelfState();
		assertFalse(s.isFrozen(0));
		assertFalse(s.isFrozen(1000));
	}

	// ── Cancellation / reset ─────────────────────────────────────────────────

	@Test
	public void clearFreeze_cancelsActiveTimer()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.clearFreeze();
		assertFalse(s.isFrozen(5));
		assertEquals(0, s.getFreezeTicksRemaining(5));
		assertEquals(0, s.getFreezeSpriteId());
	}

	@Test
	public void reset_clearsActiveFreezeTimer()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.reset();
		assertFalse(s.isFrozen(10));
		assertEquals(0, s.getFreezeTicksRemaining(10));
		assertEquals(0, s.getFreezeSpriteId());
	}

	@Test
	public void afterClear_newFreezeCanBeApplied()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.clearFreeze();
		s.applyFreeze(5, 24, SpriteID.SPELL_ICE_BLITZ); // new freeze after cancellation
		assertEquals(24, s.getFreezeTicksRemaining(5));
	}

	// ── No freeze by default ─────────────────────────────────────────────────

	@Test
	public void noFreezeByDefault()
	{
		SelfState s = new SelfState();
		assertEquals(0, s.getFreezeTicksRemaining(0));
		assertEquals(0, s.getFreezeSpriteId());
		assertFalse(s.isFrozen(0));
	}

	// ── freezeStartTick — movement-thaw same-tick guard ──────────────────────

	@Test
	public void getFreezeStartTick_returnsApplyTick()
	{
		SelfState s = new SelfState();
		s.applyFreeze(42, 8, SpriteID.SPELL_BIND);
		assertEquals(42, s.getFreezeStartTick());
	}

	@Test
	public void getFreezeStartTick_clearedAfterClearFreeze()
	{
		SelfState s = new SelfState();
		s.applyFreeze(10, 8, SpriteID.SPELL_BIND);
		s.clearFreeze();
		assertEquals(-1, s.getFreezeStartTick());
	}

	// ── thaw — post-freeze refreeze immunity ─────────────────────────────────

	@Test
	public void expireFreeze_grantsFixedImmunityWindow()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.expireFreeze(32); // natural expiry at tick 32
		assertEquals(SelfState.REFREEZE_IMMUNITY_TICKS, s.getRefreezeImmunityTicks(32));
	}

	@Test
	public void expireFreeze_immunityExpires_afterFiveTicks()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 16, SpriteID.SPELL_ICE_BURST);
		s.expireFreeze(16);
		assertTrue(s.isRefreezeImmune(16));
		assertTrue(s.isRefreezeImmune(20));  // tick 16 + 4 = 20 < 21
		assertFalse(s.isRefreezeImmune(21)); // tick 16 + 5 = 21, immunity ended
	}

	@Test
	public void breakFreezeEarly_clearsFreezeState_noImmunity()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 24, SpriteID.SPELL_ICE_BLITZ);
		s.breakFreezeEarly(); // movement detected
		assertFalse(s.isFrozen(10));
		assertEquals(0, s.getFreezeTicksRemaining(10));
		assertEquals(-1, s.getFreezeStartTick());
		assertEquals(0, s.getFreezeSpriteId());
		assertFalse("breakFreezeEarly must not grant refreeze immunity", s.isRefreezeImmune(10));
	}

	@Test
	public void expireFreeze_immunityIsSameDurationRegardlessOfSpell()
	{
		// Immunity must be the same fixed value for every freeze type
		SelfState rush = new SelfState();
		rush.applyFreeze(0, 8, SpriteID.SPELL_ICE_RUSH);
		rush.expireFreeze(8);

		SelfState barrage = new SelfState();
		barrage.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		barrage.expireFreeze(32);

		assertEquals(SelfState.REFREEZE_IMMUNITY_TICKS, rush.getRefreezeImmunityTicks(8));
		assertEquals(SelfState.REFREEZE_IMMUNITY_TICKS, barrage.getRefreezeImmunityTicks(32));
	}

	// ── clearFreeze — no immunity granted ────────────────────────────────────

	@Test
	public void clearFreeze_doesNotGrantImmunity()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.clearFreeze(); // logout/world-hop — must NOT create immunity
		assertFalse(s.isRefreezeImmune(0));
		assertEquals(0, s.getRefreezeImmunityTicks(0));
	}

	@Test
	public void reset_doesNotGrantImmunity()
	{
		SelfState s = new SelfState();
		s.applyFreeze(0, 32, SpriteID.SPELL_ICE_BARRAGE);
		s.reset();
		assertFalse(s.isRefreezeImmune(1));
		assertEquals(0, s.getRefreezeImmunityTicks(1));
	}

	// ── No refreeze immunity by default ─────────────────────────────────────

	@Test
	public void noRefreezeImmunityByDefault()
	{
		SelfState s = new SelfState();
		assertFalse(s.isRefreezeImmune(0));
		assertEquals(0, s.getRefreezeImmunityTicks(0));
	}
}

package com.pvphud;

import com.pvphud.state.SelfState;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Exercises the production {@link PvpHudPlugin#recordIncomingDamage(SelfState, int, long)}
 * helper used by {@code onHitsplatApplied}. Zero and negative damage must leave
 * both shake fields untouched; positive damage must overwrite both.
 */
public class SelfStateHpShakeTest
{
	@Test
	public void zeroDamage_doesNotUpdate()
	{
		SelfState self = new SelfState();
		long before = self.getLastIncomingDamageMs();
		PvpHudPlugin.recordIncomingDamage(self, 0, 99999L);
		assertEquals("timestamp unchanged on zero damage", before, self.getLastIncomingDamageMs());
		assertEquals("amount unchanged on zero damage", 0, self.getLastIncomingDamage());
	}

	@Test
	public void negativeDamage_doesNotUpdate()
	{
		SelfState self = new SelfState();
		long before = self.getLastIncomingDamageMs();
		PvpHudPlugin.recordIncomingDamage(self, -1, 99999L);
		assertEquals(before, self.getLastIncomingDamageMs());
		assertEquals(0, self.getLastIncomingDamage());
	}

	@Test
	public void positiveDamage_updatesTimestampAndAmount()
	{
		SelfState self = new SelfState();
		PvpHudPlugin.recordIncomingDamage(self, 18, 12345L);
		assertEquals(12345L, self.getLastIncomingDamageMs());
		assertEquals(18, self.getLastIncomingDamage());
	}

	@Test
	public void secondHit_overwritesBothFields()
	{
		SelfState self = new SelfState();
		PvpHudPlugin.recordIncomingDamage(self, 10, 1000L);
		PvpHudPlugin.recordIncomingDamage(self, 25, 2000L);
		assertEquals(2000L, self.getLastIncomingDamageMs());
		assertEquals(25, self.getLastIncomingDamage());
	}

	@Test
	public void reset_clearsShakeState()
	{
		SelfState self = new SelfState();
		PvpHudPlugin.recordIncomingDamage(self, 25, System.currentTimeMillis());
		self.reset();
		assertEquals(-1L, self.getLastIncomingDamageMs());
		assertEquals(0,   self.getLastIncomingDamage());
	}
}

package com.pvphud;

import com.pvphud.state.EffectState;
import com.pvphud.state.PoisonState;
import com.pvphud.state.SelfState;
import java.util.List;
import java.util.stream.Collectors;
import net.runelite.api.SpriteID;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for {@link StatusProjector#project}.
 *
 * Uses {@code showAll=true} + {@code null} config so all effects emit regardless
 * of user settings, and the tests run without a RuneLite environment.
 */
public class StatusProjectorTest
{
	private static final int TICK = 100;

	// ── Helpers ──────────────────────────────────────────────────────────────

	private static List<StatusSlot> project(SelfState self, EffectState fx,
		PoisonState poison)
	{
		return StatusProjector.project(self, fx, poison, TICK, null, true);
	}

	private static List<String> slotIds(List<StatusSlot> slots)
	{
		return slots.stream().map(s -> s.slotId).collect(Collectors.toList());
	}

	private static StatusSlot find(List<StatusSlot> slots, String slotId)
	{
		return slots.stream().filter(s -> s.slotId.equals(slotId)).findFirst().orElse(null);
	}

	// ── Lifecycle: Freeze ↔ Refreeze Immunity ────────────────────────────────

	@Test
	public void frozen_showsFreezeSlot_notRefreezeImm()
	{
		SelfState self = new SelfState();
		self.applyFreeze(TICK - 1, 20, SpriteID.SPELL_ICE_BARRAGE); // 19 ticks remaining

		List<StatusSlot> slots = project(self, new EffectState(), new PoisonState());
		List<String> ids = slotIds(slots);

		assertTrue("freeze_barrage must appear when frozen", ids.contains("freeze_barrage"));
		assertFalse("freeze_imm must not appear while frozen", ids.contains("freeze_imm"));
	}

	@Test
	public void refreezeImm_showsRefreezeSlot_notFreeze()
	{
		SelfState self = new SelfState();
		self.applyFreeze(TICK - 20, 20, SpriteID.SPELL_ICE_BARRAGE); // freeze expired
		self.expireFreeze(TICK);                                              // grants immunity

		List<StatusSlot> slots = project(self, new EffectState(), new PoisonState());
		List<String> ids = slotIds(slots);

		assertTrue("freeze_imm must appear after thaw", ids.contains("freeze_imm"));
		assertFalse("freeze_barrage must not appear when not frozen",
			ids.contains("freeze_barrage"));
	}

	@Test
	public void refreezeImm_labelUsesTicks_notSeconds()
	{
		SelfState self = new SelfState();
		self.applyFreeze(TICK - 20, 20, SpriteID.SPELL_ICE_BARRAGE);
		self.expireFreeze(TICK); // immunity = 5 ticks

		StatusSlot slot = find(
			project(self, new EffectState(), new PoisonState()),
			"freeze_imm");
		assertNotNull(slot);
		assertEquals("REFRZ 5t", slot.textLabel);
	}

	@Test
	public void freeze_neverMoreThanOneLifecycleSlot()
	{
		// frozen: exactly one freeze slot
		SelfState frozen = new SelfState();
		frozen.applyFreeze(TICK - 1, 20, SpriteID.SPELL_ICE_BARRAGE);
		List<String> frozenIds = slotIds(
			project(frozen, new EffectState(), new PoisonState()));
		long frozenCount = frozenIds.stream()
			.filter(id -> id.startsWith("freeze_")).count();
		assertEquals("exactly one freeze slot while frozen", 1, frozenCount);

		// immune: exactly one immunity slot
		SelfState immune = new SelfState();
		immune.applyFreeze(TICK - 20, 20, SpriteID.SPELL_ICE_BARRAGE);
		immune.expireFreeze(TICK);
		List<String> immuneIds = slotIds(
			project(immune, new EffectState(), new PoisonState()));
		long immuneCount = immuneIds.stream()
			.filter(id -> id.startsWith("freeze_")).count();
		assertEquals("exactly one freeze slot during immunity", 1, immuneCount);

		// normal: zero freeze slots
		SelfState normal = new SelfState();
		List<String> normalIds = slotIds(
			project(normal, new EffectState(), new PoisonState()));
		long normalCount = normalIds.stream()
			.filter(id -> id.startsWith("freeze_")).count();
		assertEquals("zero freeze slots when not frozen or immune", 0, normalCount);
	}

	@Test
	public void freeze_iceBurst_usesBurstSlotId()
	{
		SelfState self = new SelfState();
		self.applyFreeze(TICK - 1, 16, SpriteID.SPELL_ICE_BURST);

		List<String> ids = slotIds(project(self, new EffectState(), new PoisonState()));
		assertTrue(ids.contains("freeze_burst"));
	}

	// ── Lifecycle: Teleblock ↔ TB Immunity ───────────────────────────────────

	@Test
	public void tbd_showsTbSlot_notTbImm()
	{
		SelfState self = new SelfState();
		self.setTeleBlockTicksRemaining(300);
		self.setTbImmunityActive(false);

		List<String> ids = slotIds(project(self, new EffectState(), new PoisonState()));
		assertTrue("tb must appear when TB'd", ids.contains("tb"));
		assertFalse("tb_imm must not appear when TB'd", ids.contains("tb_imm"));
	}

	@Test
	public void tbImm_showsTbImmSlot_notTb()
	{
		SelfState self = new SelfState();
		self.setTeleBlockTicksRemaining(0);
		self.setTbImmunityActive(true);

		List<String> ids = slotIds(project(self, new EffectState(), new PoisonState()));
		assertFalse("tb must not appear when only immune", ids.contains("tb"));
		assertTrue("tb_imm must appear when TB immune", ids.contains("tb_imm"));
	}

	// ── Lifecycle: Ward ↔ Ward CD ────────────────────────────────────────────

	@Test
	public void ward_active_showsWard_notWardCd()
	{
